/* ── Merge les posts d'un utilisateur reçus depuis Firebase ── */
function _gwMergePost(snap) {
  if (!snap) return;
  /* Capture les Shorts existants avant merge pour détecter les nouvelles URLs */
  var _preShorts = {};
  DEMO_POSTS.forEach(function(p) {
    if (p && p.video && p.video.videoType === 'short') {
      _preShorts[String(p.id)] = p.video.url || '';
    }
  });
  try { _gwPostsMerge(snap.key, snap.val()); } catch(e) {}
  /* Injecte les Shorts qui ont reçu une URL Firebase après le merge */
  try {
    var _newShorts = [];
    DEMO_POSTS.forEach(function(p) {
      if (!p || !p.video || p.video.videoType !== 'short') return;
      if (!p.video.url || p.video.url.startsWith('blob:')) return;
      var _preUrl = _preShorts[String(p.id)];
      var _isNew  = (_preUrl === undefined);          /* Short jamais vu avant le merge */
      var _isUpd  = (_preUrl !== undefined && !_preUrl); /* Short connu sans URL, maintenant avec */
      if (_isNew || _isUpd) {
        _newShorts.push(p);
        try {
          var _vEl = document.getElementById('fv-' + p.id);
          if (_vEl && (!_vEl.getAttribute('src') || _vEl.src.startsWith('blob:'))) {
            _gwPlayHLS(_vEl, p.video.url); _vEl.load();
          }
        } catch(e2) {}
      }
    });
    if (_newShorts.length) {
      setTimeout(function() { try { _gwPreloadShortUrls(); } catch(e) {} }, 500);
      setTimeout(function() { try { _vsInjectNewShorts(_newShorts); } catch(e) {} }, 700);
    }
  } catch(e) {}
}


/* ── Merge messages d'un groupe depuis Firebase ── */
function _gwMergeGroupMsg(snap) {
  if (!_currentUser || !snap) return;
  var fbKey = snap.key;
  /* Groupes libres (Phase GROUPS-FREE-02) : chemin entièrement parallèle,
     jamais gw_grp_{projId}___{ownerEmail} (collab, ci-dessous, inchangé).
     GROUPS/MOBILE-ANR-01 (P1) : ne route plus vers _gwMergeFreeGroupMsg (qui
     retraitait l'historique COMPLET du groupe à chaque message — cause
     racine confirmée de l'ANR mobile après ~5-6 min). Les groupes libres ont
     désormais leurs propres listeners incrémentaux par groupe, attachés via
     _attachFreeGroupRealtimeListeners (child_added sur .../messages, coût
     O(1) par message). Les groupes de collaboration ci-dessous restent
     entièrement inchangés — seul ce chemin top-level free-group est retiré. */
  if (fbKey && fbKey.indexOf('gw_grp_adhoc_') === 0) { return; }
  var data  = snap.val();
  if (!data) return;
  var lsKey = fbKey.replace(/__d__/g, '.').replace(/__a__/g, '@');
  /* S'assurer que les conversations de groupe sont chargées avant la recherche */
  if (!_groupConvsReady) { try { _loadGroupConvs(); } catch(e){} }
  /* Vérifier que ce groupe concerne l'utilisateur courant */
  var conv = DEMO_CONVERSATIONS.find(function(c) {
    return c.isGroup && _getGroupMsgKey(c.projId, c.projOwnerEmail) === lsKey;
  });
  if (!conv) return;
  try {
    /* Normalise : Firebase stocke les messages comme objet {id:msg} ou tableau */
    var rawMsgs = data.messages;
    var incomingMsgs = Array.isArray(rawMsgs) ? rawMsgs
      : (rawMsgs && typeof rawMsgs === 'object') ? Object.values(rawMsgs) : [];
    if (!incomingMsgs.length) return;

    var existing = null;
    try { existing = JSON.parse(localStorage.getItem(lsKey)); } catch(e){}
    var stored = (existing && Array.isArray(existing.messages)) ? existing.messages : [];
    var storedMap = {};
    stored.forEach(function(m) { storedMap[String(m.id)] = true; });
    var newMsgsGrp = [];
    incomingMsgs.forEach(function(m) {
      if (m && m.id && !storedMap[String(m.id)]) { stored.push(m); newMsgsGrp.push(m); }
    });
    var changed = newMsgsGrp.length > 0;
    if (changed) {
      stored.sort(function(a, b) { return (Number(a.id)||0) - (Number(b.id)||0); });
      var _lastGrpMsg = newMsgsGrp[newMsgsGrp.length - 1];
      var _lastGrpText = _lastGrpMsg.text || (data.lastMsg || '');
      try { localStorage.setItem(lsKey, JSON.stringify({ messages: stored, lastMsg: _lastGrpText, lastAt: data.lastAt || Date.now() })); } catch(e){}

      /* ── Met à jour le conv en mémoire + rendu DOM direct ── */
      var _grpChatBox  = document.getElementById('chat-messages');
      var _grpChatOpen = _chatConvId === conv.id && _grpChatBox;

      newMsgsGrp.forEach(function(m) {
        if (conv.messages.some(function(x){ return String(x.id) === String(m.id); })) return;
        conv.messages.push(m);

        /* Rendu direct — évite le bug _pollGroupMessages / convMap déjà rempli */
        if (_grpChatOpen && m.from !== _currentUser.email) {
          if (!_grpChatBox.querySelector('[data-msg-id="' + m.id + '"]')) {
            var _grpRow = document.createElement('div');
            if (m.from === 'system') {
              _grpRow.className = 'chat-sys-msg';
              _grpRow.textContent = m.text || '';
            } else {
              var _sProfile = loadUserProfile(m.from) || {};
              var _sName    = _sProfile.nom || m.from || '';
              var _sAv = _sProfile.photo
                ? '<img src="' + _sProfile.photo + '" class="chat-group-av" alt="">'
                : '<div class="chat-group-av chat-group-av-init">' + escHtml(_sName.charAt(0).toUpperCase()) + '</div>';
              var _sHdr = '<div class="chat-group-sender-row">' + _sAv +
                '<span class="chat-group-sender-name">' + escHtml(_sName) + '</span></div>';
              _grpRow.className = 'chat-msg-row theirs';
              _grpRow.setAttribute('data-msg-id', m.id);
              _grpRow.innerHTML = _sHdr + _buildBubbleHtml(m, false);
            }
            _grpChatBox.appendChild(_grpRow);
          }
        }
      });

      conv.messages.sort(function(a,b){ return (Number(a.id)||0)-(Number(b.id)||0); });
      conv.lastMsg = _lastGrpText;
      conv.lastAt  = data.lastAt || Date.now();

      if (_grpChatOpen) {
        try { _scrollChatToBottom(); } catch(e4){}
      } else {
        conv.unread = (conv.unread || 0) + newMsgsGrp.filter(function(m) {
          return m.from !== _currentUser.email;
        }).length;
      }
      renderConversations();
    }
  } catch(e){}
}

/* ── Active le listener notifs pour un utilisateur ── */
/* ══════════════════════════════════════════
   PRÉSENCE EN LIGNE — Temps réel admin
══════════════════════════════════════════ */
var _gwOnlineRef = null;
var _gwOnlineHeartbeatTimer = null;

function _gwSetOnlinePresence(user) {
  if (!_gwFbReady || !_gwFbDB || !user) return;
  /* Respecte "Afficher le statut en ligne" — ne publie même pas la présence si désactivé */
  if (_privLoadForEmail(user.email).showOnline === false) return;
  var fbKey = _gwFbKey(user.email);
  var ref   = _gwFbDB.ref('gw/online/' + fbKey);

  /* GROUPS/MOBILE-ANR-01 (P2) : l'ancien code réassignait _gwOnlineRef AVANT
     de tester son ancien ._heartbeat — la garde "clear avant recréation"
     inspectait donc toujours le NOUVEAU ref (jamais encore initialisé),
     jamais l'ancien, laissant un setInterval(120000) orphelin actif à
     chaque appel (confirmé par test : 5 appels → 5 intervals actifs).
     Le timer est maintenant suivi indépendamment du ref et nettoyé AVANT
     toute réassignation — un seul heartbeat actif, quel que soit le
     nombre d'appels. */
  if (_gwOnlineHeartbeatTimer) { clearInterval(_gwOnlineHeartbeatTimer); _gwOnlineHeartbeatTimer = null; }

  _gwOnlineRef = ref;

  /* Écrit la présence (peut échouer si auth pas encore établie → silencieux) */
  ref.set({
    nom:   user.nom   || user.email,
    email: user.email,
    at:    Date.now()
  }).catch(function(){});

  /* Supprime automatiquement à la déconnexion */
  ref.onDisconnect().remove().catch(function(){});

  /* Renouvelle la présence toutes les 2 minutes (keepalive) */
  _gwOnlineHeartbeatTimer = setInterval(function() {
    try { ref.update({ at: Date.now() }); } catch(e){}
  }, 120000);
}

/* ── Listener présence en ligne — temps réel pour toute l'app ── */
function _gwWatchOnlineUsers() {
  if (!_gwFbReady || !_gwFbDB) return;
  _gwFbDB.ref('gw/online').on('value', function(snap) {
    var data  = snap.val() || {};
    var count = Object.keys(data).length;
    localStorage.setItem('gw_online_count', count);

    /* Met à jour le compteur admin */
    var el = document.getElementById('adm-online-count');
    if (el) el.textContent = count;
    if (_adminUser && _adminTab === 'dashboard') {
      try { _admRender(); } catch(e){}
    }

    /* ── Mise à jour des statuts en ligne dans les conversations ── */
    /* Construire l'ensemble des emails en ligne */
    var onlineEmails = {};
    Object.values(data).forEach(function(entry) {
      if (entry && entry.email && _privLoadForEmail(entry.email).showOnline !== false) {
        onlineEmails[entry.email.toLowerCase()] = true;
      }
    });

    /* Mettre à jour conv.online pour chaque DM */
    var changed = false;
    DEMO_CONVERSATIONS.forEach(function(conv) {
      if (conv.isGroup || !conv.email) return;
      var isNowOnline = !!onlineEmails[conv.email.toLowerCase()];
      if (conv.online !== isNowOnline) {
        conv.online = isNowOnline;
        changed = true;
      }
    });

    /* Rafraîchir la liste des conversations si un statut a changé */
    if (changed) {
      var msgPage = document.getElementById('p-messages');
      if (msgPage && msgPage.classList.contains('active')) {
        try { renderConversations(); } catch(e) {}
      }
    }

    /* Mettre à jour l'en-tête du chat ouvert */
    if (_chatConvId) {
      var openConv = DEMO_CONVERSATIONS.find(function(c) { return c.id === _chatConvId; });
      if (openConv && !openConv.isGroup) {
        var statusEl = document.getElementById('chat-contact-status');
        if (statusEl) {
          statusEl.textContent = openConv.online ? 'En ligne' : 'Hors ligne';
          statusEl.style.color = openConv.online ? '#22C55E' : '#94A3B8';
        }
      }
    }
  });
}

function _gwGetOnlineCount() {
  return parseInt(localStorage.getItem('gw_online_count') || '0', 10);
}

function _gwFbWatchUserNotifs(email) {
  if (!_gwFbReady || !_gwFbDB || !email) return;
  _gwFbDB.ref('gw/notifs/' + _gwFbKey(email)).on('value', function(snap) {
    if (_gwFbSkip) return;
    var data = snap.val();
    if (data === null) return;
    _gwFbSkip = true;
    /* Firebase .push() stocke sous forme d'objet {pushKey: {...}} → normaliser en tableau */
    var arr;
    if (Array.isArray(data)) {
      arr = data.filter(Boolean);
    } else if (data && typeof data === 'object') {
      arr = Object.keys(data).map(function(k) {
        var n = data[k];
        if (n && !n.id) n.id = k;
        return n;
      }).filter(Boolean);
    } else {
      arr = [];
    }
    /* Trier du plus récent au plus ancien */
    arr.sort(function(a, b) { return (b.at || 0) - (a.at || 0); });
    /* Phase SYNC-OPTIONS-03 : écriture protégée, voir _listen() plus haut. */
    try { localStorage.setItem('gw_notifs_' + email, JSON.stringify(arr)); }
    catch(e) { _gwLog('LS_QUOTA_EXCEEDED', { key: 'gw_notifs_' + email, status: 'NOTIFS_CACHE_WRITE_FAILED', error: e && e.name }); }
    _gwFbSkip = false;
    try { renderNotifs(); updateNotifBadge(); } catch(e){}
  });
}

/* ── Active le listener abonnés (index inversé gw/followers/{myFbKey}) ── */
function _gwFbWatchFollowers(email) {
  if (!_gwFbReady || !_gwFbDB || !email) return;
  _gwFbDB.ref('gw/followers/' + _gwFbKey(email)).on('value', function(snap) {
    try {
      var data = snap.val();
      /* Convertit l'objet {fbKey: {nom,email,role}} en tableau */
      var followers = data
        ? Object.values(data).filter(function(f) { return f && f.email; })
        : [];
      localStorage.setItem('gw_followers_' + email, JSON.stringify(followers));
      /* Met à jour pstat-followers si le profil perso est affiché */
      var myKey  = getProfileKey({ nom: _currentUser ? _currentUser.nom : '', email: email });
      var follEl = document.getElementById('pstat-followers');
      if (follEl && _currentUser && _currentUser.email === email) {
        follEl.textContent = _getTotalFollowers(myKey, false);
      }
    } catch(e){}
  });
}

/* ── Upload initial : envoie le localStorage existant vers Firebase ── */
function _gwFbUploadAll() {
  if (!_gwFbReady) { showToast('Firebase non connecté', 'err'); return; }
  if (!confirm('Envoyer toutes les données locales vers Firebase ?')) return;
  var pairs = [
    ['users',          'gw_users'],
    ['bans',           'gw_bans'],
    ['ban_appeals',    'gw_ban_appeals'],
    ['admins',         'gw_admins'],
    ['sadmin',         'gw_sadmin'],
    ['official_posts', 'gw_official_posts'],
    ['admin_log',      'gw_admin_log'],
    ['settings_logo',  'gw_official_logo'],
  ];
  pairs.forEach(function(p) {
    var raw = localStorage.getItem(p[1]);
    if (raw) { try { _gwFbSet(p[0], JSON.parse(raw)); } catch(e){} }
  });
  /* Reports + Notifs par utilisateur */
  Object.keys(localStorage).forEach(function(k) {
    if (k.startsWith('gw_reports_')) {
      var em = k.replace('gw_reports_', '');
      try { _gwFbSet('reports/' + _gwFbKey(em), JSON.parse(localStorage.getItem(k))); } catch(e){}
    }
    if (k.startsWith('gw_notifs_')) {
      var em = k.replace('gw_notifs_', '');
      try { _gwFbSet('notifs/' + _gwFbKey(em), JSON.parse(localStorage.getItem(k))); } catch(e){}
    }
  });
  showToast('Données envoyées vers Firebase ✓', 'ok');
}

/* ── Indicateur de statut Firebase (retourne HTML) ── */
function _gwFbStatusHtml() {
  if (!_gwFbReady) {
    return '<span style="display:inline-flex;align-items:center;gap:5px;font-size:12px;color:#EF4444">' +
           '<i class="fas fa-circle" style="font-size:8px"></i> Non connecté (mode local)</span>';
  }
  return '<span style="display:inline-flex;align-items:center;gap:5px;font-size:12px;color:#10B981">' +
         '<i class="fas fa-circle" style="font-size:8px"></i> Firebase connecté — Sync temps réel actif</span>';
}

