function closeVideosDiscover() {
  var modal = document.getElementById('vd-modal');
  if (modal) modal.style.display = 'none';
}

/* Applique la découpe style TikTok (début/fin uniquement) pendant la lecture —
   sans ré-encodage côté client, c'est le seul moyen de garantir que les autres
   utilisateurs voient exactement la même tranche que celle choisie à l'édition.
   L'élément vidéo étant réutilisé entre plusieurs lectures, les bornes actives
   sont stockées sur l'élément lui-même et remplacées à chaque appel. */
function _gwApplyVideoTrim(videoEl, trimStart, trimEnd) {
  if (!videoEl) return;
  videoEl._gwTrimStart = trimStart > 0 ? trimStart : 0;
  videoEl._gwTrimEnd   = (trimEnd && trimEnd > videoEl._gwTrimStart) ? trimEnd : null;
  if (videoEl._gwTrimBound) return;
  videoEl._gwTrimBound = true;
  videoEl.addEventListener('timeupdate', function() {
    var s = videoEl._gwTrimStart || 0;
    var e = videoEl._gwTrimEnd;
    if (videoEl.currentTime < s) {
      videoEl.currentTime = s;
    } else if (e && videoEl.currentTime >= e) {
      if (videoEl.loop) {
        videoEl.currentTime = s;
      } else {
        videoEl.pause();
        videoEl.currentTime = e;
        videoEl.dispatchEvent(new Event('ended'));
      }
    }
  });
}

function openVideoPlayer(src, duration, cropPos, cropZoom, trimStart, trimEnd, muted, textLayers, fx) {
  var modal = document.getElementById('video-player-modal');
  var video = document.getElementById('vp-video');
  if (!modal || !video) return;
  _gwApplyVideoTrim(video, trimStart, trimEnd);
  /* Respecte le choix "Son" fait par l'auteur dans l'éditeur (vidéo régulière) */
  video.muted = !!muted;
  /* Texte/emoji ajoutés dans l'éditeur — superposés à la vidéo, comme dans son aperçu */
  var vpTextLayers = document.getElementById('vp-text-layers');
  if (vpTextLayers) vpTextLayers.innerHTML = _gwRenderTextLayersHtml(textLayers);
  /* Effets overlay (vignette/grain) + glow/zoom/intro/outro choisis dans l'éditeur */
  var vpOverlays = document.getElementById('vp-overlays');
  if (vpOverlays) vpOverlays.innerHTML = _gwRenderVideoOverlaysHtml(fx && fx.effects);
  _gwApplyVideoFx(document.getElementById('vp-area'), video, fx || {});

  /* Pause toutes les vidéos du feed pendant la lecture plein écran */
  document.querySelectorAll('[id^="fv-"]').forEach(function(v) {
    if (!v.paused) v.pause();
    var pid = v.id.replace('fv-', '');
    var ov = document.getElementById('fvo-' + pid);
    var mb = document.getElementById('fvm-' + pid);
    if (ov) ov.style.opacity = '1';
    if (mb) mb.style.opacity = '0';
  });

  /* Recadrage format YouTube choisi dans l'éditeur — applique le même cadrage
     qu'à la publication (sinon "contain" par défaut affiche la vidéo brute,
     non recadrée, ce qui contredit le choix fait avant publication) */
  var _vpCrop = (cropPos && typeof cropPos === 'object') ? cropPos : { x: 50, y: 50 };
  var _vpZoom = (cropZoom && cropZoom > 1) ? cropZoom : 1;
  video.style.objectPosition = _vpCrop.x + '% ' + _vpCrop.y + '%';

  /* Source — preload auto + force le navigateur à commencer le buffer immédiatement */
  video.preload = 'auto';
  video.playsInline = true;
  /* Pas de translateZ(0) : force une couche 3D GPU qui blackscreen la vidéo
     sur certains Android bas/moyenne gamme. scale() seul suffit pour le zoom. */
  video.style.transform  = _vpZoom > 1 ? ('scale(' + _vpZoom + ')') : '';
  video.style.transformOrigin = 'center center';
  _gwPlayHLS(video, src);
  video.load(); /* force le fetch immédiat — évite la saccade au premier play */
  video.currentTime = 0;
  video.playbackRate = 1;

  /* Durée initiale */
  var durEl = document.getElementById('vp-dur');
  if (durEl) durEl.textContent = formatDuration(duration || 0);
  var curEl = document.getElementById('vp-cur');
  if (curEl) curEl.textContent = '0:00';
  var seek = document.getElementById('vp-seek');
  if (seek) { seek.value = 0; seek.max = duration || 100; }

  /* Reset speed UI — mark all "1×" buttons active */
  document.querySelectorAll('.vp-speed').forEach(function(b) {
    b.classList.toggle('active', (b.dataset.sp || '') === '1' || b.textContent.trim() === '1×');
  });

  /* Seek bar drag: évite que ontimeupdate écrase la position pendant le glissement */
  if (seek && !seek._gwDragBound) {
    seek._gwDragBound = true;
    seek.addEventListener('mousedown',  function() { seek._dragging = true;  });
    seek.addEventListener('touchstart', function() { seek._dragging = true;  }, { passive: true });
    seek.addEventListener('mouseup',    function() { seek._dragging = false; });
    seek.addEventListener('touchend',   function() { seek._dragging = false; });
  }
  seek._dragging = false;

  /* Reset icône play + controls state */
  _vpSetPlayIcon(false);
  vpHideControls();
  clearTimeout(_vpCtrlTimer);

  /* Cache le panel auto-next si ouvert */
  _vpCancelAutoNextTimer();
  var anPanel = document.getElementById('vpd-autonext');
  if (anPanel) anPanel.style.display = 'none';

  /* Events vidéo */
  video.onloadedmetadata = function() {
    /* La vidéo brute n'est jamais réellement tronquée (découpe = lecture
       virtuelle) — video.duration renvoie donc toujours la durée d'origine.
       On affiche la durée découpée (fin de coupe) si elle existe, sinon brute. */
    var d = (video._gwTrimEnd) ? video._gwTrimEnd : video.duration;
    if (durEl) durEl.textContent = formatDuration(d);
    if (seek)  seek.max = d;
  };
  video.ontimeupdate = function() {
    if (seek && !seek._dragging) seek.value = video.currentTime;
    if (curEl) curEl.textContent = formatDuration(video.currentTime);
    _vpUpdateSeekGradient();
  };
  video.onplay = function() {
    _vpSetPlayIcon(true);
    _vpResetHideTimer(); /* auto-cacher dans 3s */
  };
  video.onpause = function() {
    _vpSetPlayIcon(false);
    clearTimeout(_vpCtrlTimer);
    vpShowControls(); /* rester visible quand en pause */
  };
  video.onended = function() {
    _vpSetPlayIcon(false);
    vpShowControls();
    clearTimeout(_vpCtrlTimer);
    _vpStartAutoNext(); /* proposer la vidéo suivante */
  };

  modal.style.display = 'flex';

  /* Lance la lecture : immédiate si buffer suffisant, sinon attend canplaythrough */
  vpShowControls();
  if (video.readyState >= 3) {
    video.play().catch(function(){});
  } else {
    var _vpOnReady = function() {
      video.removeEventListener('canplay', _vpOnReady);
      video.play().catch(function(){});
    };
    video.addEventListener('canplay', _vpOnReady);
  }
}

function closeVideoPlayer() {
  var video = document.getElementById('vp-video');
  if (video) { video.pause(); video.src = ''; video.ontimeupdate = null; video.onended = null; }
  if (_vpCommentsTimer) { clearInterval(_vpCommentsTimer); _vpCommentsTimer = null; }
  var modal = document.getElementById('video-player-modal');
  if (modal) modal.style.display = 'none';
  /* Quitte le plein écran si actif */
  if (document.fullscreenElement || document.webkitFullscreenElement) {
    (document.exitFullscreen || document.webkitExitFullscreen || function(){}).call(document);
  }
  /* Réactive l'autoplay feed */
  _initFeedVideoObserver();
}

/* ── Controls show/hide (tap-to-reveal, auto-hide 3s when playing) ── */
var _vpCtrlTimer   = null;
var _vpCtrlVisible = false;

function vpShowControls() {
  var ov = document.getElementById('vpd-ctrl-overlay');
  if (ov) ov.classList.add('visible');
  _vpCtrlVisible = true;
}
function vpHideControls() {
  var ov = document.getElementById('vpd-ctrl-overlay');
  if (ov) ov.classList.remove('visible');
  _vpCtrlVisible = false;
}
function _vpResetHideTimer() {
  clearTimeout(_vpCtrlTimer);
  var video = document.getElementById('vp-video');
  if (video && !video.paused) {
    _vpCtrlTimer = setTimeout(vpHideControls, 3000);
  }
}
/* Tapping the video area:
   - Controls hidden → show them + start 3s hide timer
   - Controls visible + tap on overlay bg → play/pause  */
function vpAreaTap(e) {
  if (e) e.stopPropagation();
  if (!_vpCtrlVisible) {
    vpShowControls();
    _vpResetHideTimer();
  } else {
    /* Only toggle play if the tap landed on the overlay itself (not on a button inside) */
    if (!e || e.target === document.getElementById('vpd-ctrl-overlay')) {
      vpTogglePlay();
    }
  }
}

function vpTogglePlay() {
  var video = document.getElementById('vp-video');
  if (!video) return;
  var wasPaused = video.paused;
  if (wasPaused) {
    video.play();
    _vpResetHideTimer();
  } else {
    video.pause();
    clearTimeout(_vpCtrlTimer); /* stay visible while paused */
    vpShowControls();
  }
  _vpFlash(wasPaused ? 'fa-play' : 'fa-pause');
}

function _vpSetPlayIcon(playing) {
  var ico = document.getElementById('vp-play-ico');
  if (ico) ico.className = playing ? 'fas fa-pause' : 'fas fa-play';
  /* Ajustement padding visuel play vs pause */
  var btn = document.getElementById('vp-play-btn');
  if (btn) btn.style.paddingLeft = playing ? '0' : '3px';
}

function _vpFlash(iconClass) {
  var flash = document.getElementById('vp-play-flash');
  if (!flash) return;
  flash.innerHTML = '<i class="fas ' + iconClass + '"></i>';
  flash.classList.add('show');
  clearTimeout(_vpFlashTimer);
  _vpFlashTimer = setTimeout(function() { flash.classList.remove('show'); }, 500);
}

function vpSeek(val) {
  var video = document.getElementById('vp-video');
  if (video) video.currentTime = parseFloat(val);
  _vpUpdateSeekGradient();
}

function _vpUpdateSeekGradient() {
  var seek = document.getElementById('vp-seek');
  var video = document.getElementById('vp-video');
  if (!seek || !video || !video.duration) return;
  var pct = (video.currentTime / video.duration) * 100;
  seek.style.background =
    'linear-gradient(to right, #2563EB 0%, #2563EB ' + pct + '%, rgba(255,255,255,.25) ' + pct + '%)';
}

function vpSkip(sec) {
  var video = document.getElementById('vp-video');
  if (!video) return;
  video.currentTime = Math.max(0, Math.min(video.duration || 0, video.currentTime + sec));
  vpShowControls();
  _vpResetHideTimer();
}

function vpSetSpeed(speed, btn) {
  var video = document.getElementById('vp-video');
  if (video) video.playbackRate = speed;
  /* Sync ALL speed buttons (overlay + speed bar) by data-sp attribute */
  var sp = String(speed);
  document.querySelectorAll('.vp-speed').forEach(function(b) {
    b.classList.toggle('active', (b.dataset.sp || b.textContent.replace('×','').trim()) === sp);
  });
  vpShowControls();
  _vpResetHideTimer();
}

function vpFullscreen() {
  var area  = document.getElementById('vp-area');
  var video = document.getElementById('vp-video');

  /* iOS WebKit — webkitEnterFullscreen gère la rotation automatiquement */
  if (video && video.webkitEnterFullscreen) {
    video.webkitEnterFullscreen();
    return;
  }

  var target = area || video;
  if (!target) return;
  var req = target.requestFullscreen || target.webkitRequestFullscreen || target.mozRequestFullScreen;
  if (!req) return;

  req.call(target).then(function() {
    /* Verrouille l'orientation en paysage après le passage en plein écran */
    try {
      if (screen && screen.orientation && screen.orientation.lock) {
        screen.orientation.lock('landscape').catch(function() {});
      }
    } catch(e) {}
  }).catch(function() {});
}

/* Déverrouille l'orientation quand on quitte le plein écran */
document.addEventListener('fullscreenchange', function() {
  if (!document.fullscreenElement) {
    try {
      if (screen && screen.orientation && screen.orientation.unlock) {
        screen.orientation.unlock();
      }
    } catch(e) {}
  }
});

/* ══════════════════════════════════════════
   TRADUCTION DE POST (MyMemory API)
══════════════════════════════════════════ */
function translatePost(postId) {
  var post = getAllPosts().find(function(p) { return p.id === postId; });
  if (!post || !post.text) return;

  var btn    = document.getElementById('translate-btn-' + postId);
  var textEl = document.getElementById('ptxt-' + postId);
  if (!btn || !textEl) return;

  /* Bascule : si déjà traduit, revient à l'original */
  if (btn.dataset.translated === '1') {
    textEl.textContent = post.text;
    btn.innerHTML = '<i class="fas fa-language"></i> ' + t('post.translate');
    btn.dataset.translated = '0';
    btn.disabled = false;
    return;
  }

  btn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> ' + t('post.translating');
  btn.disabled  = true;

  /* Si UI en FR → traduit vers EN, sinon vers FR */
  var lang     = _getCurrentLang();
  var langpair = lang === 'fr' ? 'fr|en' : 'en|fr';
  var query    = post.text.slice(0, 500);

  fetch('https://api.mymemory.translated.net/get?q=' +
        encodeURIComponent(query) + '&langpair=' + langpair)
    .then(function(r) { return r.json(); })
    .then(function(data) {
      var translated = data.responseData && data.responseData.translatedText;
      if (translated && translated !== query) {
        textEl.textContent = translated;
        btn.innerHTML = '<i class="fas fa-rotate-left"></i> ' + t('post.see_orig');
        btn.dataset.translated = '1';
      } else {
        btn.innerHTML = '<i class="fas fa-language"></i> ' + t('post.translate');
      }
      btn.disabled = false;
    })
    .catch(function() {
      btn.innerHTML = '<i class="fas fa-language"></i> ' + t('post.translate');
      btn.disabled  = false;
      showToast('Traduction indisponible', 'err');
    });
}

function formatFileSize(bytes) {
  if (bytes < 1024 * 1024) return Math.round(bytes / 1024) + ' Ko';
  return (bytes / (1024 * 1024)).toFixed(1) + ' Mo';
}

/* ══════════════════════════════════════════════════════════════
   SYSTÈME DE LIMITES PAR PLAN
   Applique automatiquement les restrictions selon profile.planType
════════════════════════════════════════════════════════════════ */

/* ── Définition des limites par plan ── */
var _PLAN_LIMITS = {
  free: {
    postsPerDay    : 5,
    msgsPerDay     : 10,
    photosPerDay   : 10,
    docsPerDay     : 10,
    servicesMax    : 3,
    projectsMax    : 5,
    photosPerPost  : 3,
    photosSvc      : 2,
    collabPerMonth : 4        /* 4 annonces de collaboration par mois */
  },
  premium: {
    postsPerDay    : Infinity,
    msgsPerDay     : Infinity,
    photosPerDay   : Infinity,
    docsPerDay     : Infinity,
    servicesMax    : 10,
    projectsMax    : Infinity,
    photosPerPost  : 6,
    photosSvc      : 4,
    collabPerMonth : 15       /* sera complété au prochain message */
  },
  business: {
    postsPerDay    : Infinity,
    msgsPerDay     : Infinity,
    photosPerDay   : Infinity,
    docsPerDay     : Infinity,
    servicesMax    : 20,
    projectsMax    : Infinity,
    photosPerPost  : 6,
    photosSvc      : 4,
    collabPerMonth : Infinity /* sera complété au prochain message */
  }
};

/* Retourne les limites du plan actuel de l'utilisateur connecté */
function _getCurrentPlanLimits() {
  if (!_currentUser) return _PLAN_LIMITS.free;
  var profile = loadUserProfile(_currentUser.email) || {};
  var plan = profile.planType || 'free';
  return _PLAN_LIMITS[plan] || _PLAN_LIMITS.free;
}

/* Met à jour le placeholder + l'état du bouton envoi selon la limite journalière */
function _updateChatMsgCounter() {
  if (!_currentUser) return;
  var inp     = document.getElementById('chat-input');
  var sendBtn = document.getElementById('chat-send-btn');
  if (!inp) return;
  var lim  = _getCurrentPlanLimits();
  if (lim.msgsPerDay === Infinity) {
    inp.disabled = false;
    inp.placeholder = 'Écrire un message...';
    if (sendBtn) sendBtn.disabled = false;
    return;
  }
  var used = _getDailyCount('msgs', _currentUser.email);
  var left = lim.msgsPerDay - used;
  if (left <= 0) {
    inp.disabled    = true;
    inp.placeholder = '🚫 Limite ' + lim.msgsPerDay + ' messages/jour atteinte — réinitialisé demain';
    if (sendBtn) sendBtn.disabled = true;
  } else if (left <= 2) {
    inp.disabled    = false;
    inp.placeholder = '⚠️ ' + left + ' message' + (left > 1 ? 's' : '') + ' restant' + (left > 1 ? 's' : '') + ' aujourd\'hui';
    if (sendBtn) sendBtn.disabled = false;
  } else {
    inp.disabled    = false;
    inp.placeholder = 'Écrire un message...';
    if (sendBtn) sendBtn.disabled = false;
  }
}

/* Clé de comptage journalier : gw_daily_{feature}_{email}_{YYYY-MM-DD} */
function _dailyKey(feature, email) {
  var today = new Date().toISOString().slice(0, 10);
  return 'gw_daily_' + feature + '_' + email + '_' + today;
}

function _getDailyCount(feature, email) {
  return parseInt(localStorage.getItem(_dailyKey(feature, email)) || '0', 10);
}

function _incDailyCount(feature, email) {
  var k = _dailyKey(feature, email);
  var n = _getDailyCount(feature, email) + 1;
  localStorage.setItem(k, n);
  return n;
}

/* ── Comptage MENSUEL : gw_monthly_{feature}_{email}_{YYYY-MM} ── */
function _monthlyKey(feature, email) {
  var ym = new Date().toISOString().slice(0, 7); /* "2026-05" */
  return 'gw_monthly_' + feature + '_' + email + '_' + ym;
}
function _getMonthlyCount(feature, email) {
  return parseInt(localStorage.getItem(_monthlyKey(feature, email)) || '0', 10);
}
function _incMonthlyCount(feature, email) {
  var k = _monthlyKey(feature, email);
  var n = _getMonthlyCount(feature, email) + 1;
  localStorage.setItem(k, n);
  return n;
}
/* Retourne le 1er du mois prochain au format lisible */
function _nextMonthReset() {
  var d = new Date();
  var next = new Date(d.getFullYear(), d.getMonth() + 1, 1);
  return next.toLocaleDateString('fr-FR', { day: 'numeric', month: 'long', year: 'numeric' });
}

/* Affiche un modal de blocage + envoie une notification à l'utilisateur */
function _showPlanLimitModal(title, desc, featureName) {
  var existing = document.getElementById('plan-limit-modal');
  if (existing) existing.remove();

  var profile   = loadUserProfile(_currentUser.email) || {};
  var plan      = profile.planType || 'free';
  var isPrem    = plan === 'premium';
  var upgTarget = isPrem ? 'Business Pro 💼' : 'Premium 👑';
  var iconPlan  = isPrem ? 'fas fa-briefcase' : 'fas fa-crown';
  var planLabel = plan === 'free' ? 'Gratuit' : plan === 'premium' ? 'Premium 👑' : 'Business Pro 💼';

  /* Heure de reset = minuit cette nuit */
  var now       = new Date();
  var tomorrow  = new Date(now.getFullYear(), now.getMonth(), now.getDate() + 1, 0, 0, 0);
  var diffMs    = tomorrow - now;
  var diffH     = Math.floor(diffMs / 3600000);
  var diffM     = Math.floor((diffMs % 3600000) / 60000);
  var resetMsg  = diffH > 0
    ? 'Réinitialisation dans <strong>' + diffH + 'h ' + diffM + 'min</strong> (minuit)'
    : 'Réinitialisation dans <strong>' + diffM + ' minutes</strong>';

  /* ── Avantages plan suivant ── */
  var benefitsHtml = isPrem
    ? '<ul class="plm-benefits"><li><i class="fas fa-check-circle"></i> Publications illimitées</li>' +
      '<li><i class="fas fa-check-circle"></i> Messages illimités</li>' +
      '<li><i class="fas fa-check-circle"></i> 20 services au lieu de 10</li>' +
      '<li><i class="fas fa-check-circle"></i> Priorité dans les résultats</li></ul>'
    : '<ul class="plm-benefits"><li><i class="fas fa-check-circle"></i> Publications illimitées</li>' +
      '<li><i class="fas fa-check-circle"></i> Messages illimités</li>' +
      '<li><i class="fas fa-check-circle"></i> 10 services au lieu de 3</li>' +
      '<li><i class="fas fa-check-circle"></i> 6 photos par publication</li></ul>';

  /* ── Notification centre de notifs (une seule fois par jour) ── */
  var notifKey = 'plmlimit_' + featureName + '_' + new Date().toISOString().slice(0,10);
  var notifs   = getNotifs(_currentUser.email);
  if (!notifs.some(function(n) { return n.id === notifKey; })) {
    notifs.unshift({
      id: notifKey, type: 'plan_limit', at: Date.now(), unread: true, fromUser: null,
      msg: '⚠️ Limite atteinte — ' + title + '. Plan ' + planLabel + '. Passez à ' + upgTarget + ' ou attendez minuit.'
    });
    saveNotifs(_currentUser.email, notifs);
    try { renderNotifs(); updateNotifBadge(); } catch(e) {}
  }

  /* ── Modal visuel ── */
  var modal = document.createElement('div');
  modal.id = 'plan-limit-modal';
  modal.className = 'plm-overlay';
  modal.innerHTML =
    '<div class="plm-sheet">' +
      '<div class="plm-icon-wrap"><i class="fas fa-lock plm-lock-icon"></i></div>' +
      '<h3 class="plm-title">Limite atteinte 🚫</h3>' +
      '<p class="plm-desc">' + escHtml(desc) + '</p>' +
      '<div class="plm-current-plan">Plan actuel : <strong>' + planLabel + '</strong></div>' +

      /* Option 1 : upgrade */
      '<div class="plm-option-card plm-option-upgrade">' +
        '<div class="plm-option-header"><i class="' + iconPlan + '" style="color:#7C3AED;margin-right:8px"></i>' +
          '<strong>Option 1 — Passer ' + upgTarget + '</strong></div>' +
        '<p class="plm-option-sub">Publiez sans aucune limite dès maintenant.</p>' +
        benefitsHtml +
        '<button class="plm-upgrade-btn" onclick="document.getElementById(\'plan-limit-modal\').remove();openSubPage()">' +
          '<i class="' + iconPlan + '"></i> Voir les offres' +
        '</button>' +
      '</div>' +

      /* Option 2 : attendre */
      '<div class="plm-option-card plm-option-wait">' +
        '<div class="plm-option-header"><i class="fas fa-clock" style="color:#0EA5E9;margin-right:8px"></i>' +
          '<strong>Option 2 — Attendre demain</strong></div>' +
        '<p class="plm-option-sub">' + resetMsg + '. Votre limite sera remise à zéro à minuit automatiquement.</p>' +
        '<button class="plm-close-btn" onclick="document.getElementById(\'plan-limit-modal\').remove()">' +
          '<i class="fas fa-times" style="margin-right:5px"></i>D\'accord, j\'attends' +
        '</button>' +
      '</div>' +
    '</div>';

  var frame = document.querySelector('.phone-frame') || document.body;
  frame.appendChild(modal);
}

/* Bannière de plan + usage dans la page profil */
function _renderPlanUsageBanner() {
  var el = document.getElementById('profil-plan-usage');
  if (!el || !_currentUser) return;
  /* ── Désactivée par le fondateur → on masque ── */
  if (!_admGetPlansConfig().bannersEnabled) { el.style.display = 'none'; return; }
  el.style.display = '';
  var profile = loadUserProfile(_currentUser.email) || {};
  var plan    = profile.planType || 'free';
  var lim     = _PLAN_LIMITS[plan] || _PLAN_LIMITS.free;

  /* Stats usage */
  var svcs     = loadUserServices(_currentUser.email).length;
  var projs    = loadProjects(_currentUser.email).length;
  var postsDay  = _getDailyCount('posts',  _currentUser.email);
  var msgsDay   = _getDailyCount('msgs',   _currentUser.email);
  var photosDay = _getDailyCount('photos', _currentUser.email);
  var docsDay   = _getDailyCount('docs',   _currentUser.email);

  var planLabels = { free: 'Gratuit', premium: 'Premium 👑', business: 'Business Pro 💼' };
  var planColors = { free: '#64748B', premium: '#D97706', business: '#4F46E5' };
  var planBgs    = { free: '#F1F5F9', premium: '#FEF3C7', business: '#EEF2FF' };
  var pLabel = planLabels[plan] || 'Gratuit';
  var pColor = planColors[plan] || '#64748B';
  var pBg    = planBgs[plan]    || '#F1F5F9';

  function _usageBar(used, max, label) {
    var pct  = max === Infinity ? 0 : Math.min(100, Math.round(used / max * 100));
    var warn = pct >= 80;
    var maxLabel = max === Infinity ? '∞' : max;
    var barColor = warn ? '#EF4444' : pColor;
    return '<div class="ppu-row">' +
      '<div class="ppu-row-label">' + label + '</div>' +
      '<div class="ppu-row-right">' +
        '<div class="ppu-bar-wrap"><div class="ppu-bar-fill" style="width:' + pct + '%;background:' + barColor + '"></div></div>' +
        '<div class="ppu-count' + (warn ? ' warn' : '') + '">' + used + ' / ' + maxLabel + '</div>' +
      '</div>' +
    '</div>';
  }

  var html = '<div class="ppu-card" style="background:' + pBg + ';border-color:' + pColor + '">' +
    '<div class="ppu-header">' +
      '<div class="ppu-plan-chip" style="color:' + pColor + '">' + pLabel + '</div>' +
      (plan !== 'business'
        ? '<button class="ppu-upgrade-btn" onclick="openSubPage()">' +
            (plan === 'free' ? '⬆ Passer Premium' : '⬆ Business Pro') +
          '</button>'
        : '<span class="ppu-max-badge">✦ Plan maximum</span>'
      ) +
    '</div>' +
    '<div class="ppu-rows">' +
      _usageBar(svcs,     lim.servicesMax,   '🛠 Services') +
      _usageBar(projs,    lim.projectsMax,   '📁 Projets') +
      _usageBar(postsDay,  lim.postsPerDay,   '✏️ Posts aujourd\'hui') +
      _usageBar(msgsDay,   lim.msgsPerDay,    '💬 Messages aujourd\'hui') +
      _usageBar(photosDay, lim.photosPerDay,  '📷 Photos aujourd\'hui') +
      _usageBar(docsDay,   lim.docsPerDay,    '📎 Documents aujourd\'hui') +
    '</div>' +
  '</div>';

  el.innerHTML = html;
}

/* ── Publication ── */
var _pubInProgress = false; /* verrou anti-double-clic */

function publierPost() {
  /* ── Anti double-clic : ignore si déjà en cours ── */
  if (_pubInProgress) return;

  var text = document.getElementById('pub-text').value.trim();

  if (!text && _pickedImages.length === 0 && !_pickedVideo && !_pickedDoc && !_quotePostRef) {
    showToast('Écrivez quelque chose ou ajoutez un média', 'err'); return;
  }

  /* ── SYNC-256 : blocage création si Vidéos/Shorts désactivés par l'admin ──
     Nécessaire en plus du masquage UI (§_gwApplyMkSections) car la capture
     caméra Short partage son bouton composeur avec Photo (non désactivable
     séparément) — ce garde-fou couvre donc aussi ce chemin, avant même
     d'atteindre la validation Firebase (qui reste le blocage réel, cf.
     database.rules.json). Vérifié ici pour éviter qu'un post "réussisse"
     localement (écriture optimiste) puis échoue silencieusement en fond lors
     de la synchronisation Firebase. */
  if (_pickedVideo) {
    var _sync256IsShort = _pickedVideo.videoType === 'short';
    var _sync256Cfg = _admGetPlansConfig();
    if (_sync256IsShort && _sync256Cfg.shortsEnabled === false) {
      showToast('Les Shorts sont temporairement désactivés', 'err'); return;
    }
    if (!_sync256IsShort && _sync256Cfg.videosEnabled === false) {
      showToast('Les vidéos sont temporairement désactivées', 'err'); return;
    }
  }

  /* ── Vérification restriction de compte ── */
  if (_currentUser && _gwIsRestricted(_currentUser.email)) {
    _pubInProgress = false;
    var _rb = document.getElementById('pub-send');
    if (_rb) { _rb.disabled = false; _rb.innerHTML = 'Publier'; }
    if (_gwShowRestrictionAlert('post')) return;
  }

  /* ── Analyse du contenu (texte) ── */
  if (_currentUser && text) {
    var _contentCheck = _gwCheckContent(text);
    if (_contentCheck.flagged) {
      showToast('🚫 Publication bloquée — ' + _contentCheck.reason, 'err');
      _gwApplyRestriction(_currentUser.email, _currentUser.nom, _contentCheck.type, _contentCheck.reason, 'auto');
      try { document.getElementById('pub-text').value = ''; } catch(e) {}
      _pubInProgress = false;
      var _rb2 = document.getElementById('pub-send');
      if (_rb2) { _rb2.disabled = false; _rb2.innerHTML = 'Publier'; }
      return;
    }
  }

  /* ── Vérification limite du plan ── */
  if (_currentUser) {
    var _pLim = _getCurrentPlanLimits();
    if (_pLim.postsPerDay !== Infinity) {
      var _todayPosts = _getDailyCount('posts', _currentUser.email);
      if (_todayPosts >= _pLim.postsPerDay) {
        _pubInProgress = false;
        var _rb3 = document.getElementById('pub-send');
        if (_rb3) { _rb3.disabled = false; _rb3.innerHTML = 'Publier'; }
        _showPlanLimitModal(
          'Limite de publications atteinte',
          'Le plan Gratuit est limité à ' + _pLim.postsPerDay + ' publications par jour. Passez Premium pour publier sans limite.',
          'posts'
        );
        return;
      }
    }
    if (_pickedImages.length > _pLim.photosPerPost) {
      showToast('Limite atteinte : ' + _pLim.photosPerPost + ' photo(s) max avec votre plan', 'err');
      _pubInProgress = false;
      var _rb4 = document.getElementById('pub-send');
      if (_rb4) { _rb4.disabled = false; _rb4.innerHTML = 'Publier'; }
      return;
    }
  }

  /* ── Verrouille le bouton + feedback visuel ── */
  _pubInProgress = true;
  var _pubSendBtn = document.getElementById('pub-send');
  if (_pubSendBtn) {
    _pubSendBtn.disabled = true;
    _pubSendBtn.innerHTML = '<i class="fas fa-spinner fa-spin" style="margin-right:5px"></i>Publication…';
  }
  function _unlockPubBtn() {
    _pubInProgress = false;
    var btn = document.getElementById('pub-send');
    if (btn) { btn.disabled = false; btn.innerHTML = 'Publier'; }
  }

  try {

  var postId      = Date.now();
  var videoBlob   = _pickedVideo ? (_pickedVideo.file || _pickedVideo.blob || null) : null;
  var videoIdbId  = _pickedVideo ? ('vid_' + postId) : null;
  /* Capture le type de vidéo avant reset UI (utilisé plus bas pour la compression) */
  var _pubIsShort = _pickedVideo && _pickedVideo.videoType === 'short';
  var docBlob     = _pickedDoc   ? (_pickedDoc.file  || null) : null;
  var docIdbId    = _pickedDoc   ? ('doc_' + postId) : null;
  /* Capturé maintenant : l'upload réel est désormais différé après le scan
     NSFW / la confirmation d'auth, et _pickedDoc sera remis à null avant
     que ce code ne s'exécute (reset du formulaire, plus bas). */
  var _docExtSnapshot        = _pickedDoc && _pickedDoc.type;
  var _docMimeSnapshot       = _pickedDoc && _pickedDoc.file && _pickedDoc.file.type || '';
  var _docStoragePathSnapshot = _pickedDoc
    ? ('post_docs/' + postId + (_pickedDoc.type ? '.' + _pickedDoc.type : '.bin'))
    : null;

  /* Pour les vidéos régulières : type et catégorie obligatoires */
  if (_pickedVideo && (_pickedVideo.videoType || 'video') === 'video' && !_pubVidMeta) {
    _unlockPubBtn();
    _showVidMetaSheet();
    return;
  }

  /* Vidéo : on stocke l'idbId + le blobUrl courant + le type (short/video) + meta */
  var videoData = _pickedVideo
    ? { idbId: videoIdbId, url: _pickedVideo.url,
        duration: (_pickedVideo.trimmedDuration != null ? _pickedVideo.trimmedDuration : _pickedVideo.duration),
        size: _pickedVideo.size,
        videoType: _pickedVideo.videoType || 'video',
        vidType:  (_pubVidMeta && _pubVidMeta.vidType)  || '',
        category: (_pubVidMeta && _pubVidMeta.category) || '',
        title:    (_pubVidMeta && _pubVidMeta.title)    || '',
        cropPos:   _pickedVideo.cropPos  || { x: 50, y: 50 },
        cropZoom:  _pickedVideo.cropZoom || 1,
        trimStart: _pickedVideo.trimStart || 0,
        trimEnd:   _pickedVideo.trimEnd   || null,
        muted:     !!_pickedVideo.muted,
        textLayers: _pickedVideo.textLayers || [],
        effects:   _pickedVideo.effects || {},
        filter:    _pickedVideo.filter  || null,
        zoom:      _pickedVideo.zoom    || null,
        zoomDur:   _pickedVideo.zoomDur || 2,
        intro:     _pickedVideo.intro   || null,
        outro:     _pickedVideo.outro   || null,
        poster:    _pickedVideo.poster   || '' }
    : null;

  /* Document : idbId + url courante + métadonnées + storagePath pour retry */
  var docData = _pickedDoc
    ? { idbId:           docIdbId,
        url:             _pickedDoc.url,
        name:            _pickedDoc.name,
        size:            _pickedDoc.size,
        ext:             _pickedDoc.type,
        mimeType:        _docMimeSnapshot,
        storagePath:     _docStoragePathSnapshot,
        storageProvider: 'firebase',
        status:          'uploading' }
    : null;

  /* ── Si un post est cité (doQuotePost) → type quote ── */
  var quoteData = null;
  if (_quotePostRef) {
    var _q = _quotePostRef;
    quoteData = {
      id:     _q.id,
      author: _q.author,
      role:   _q.role   || '',
      text:   _q.text   || '',
      images: _q.images || [],
      video:  _q.video  || null,
      doc:    _q.doc    || null
    };
  }

  var _imagesSnapshot = _pickedImages.slice();   /* copie avant reset UI */

  var newPost = {
    id:         postId,
    author:     _currentUser ? _currentUser.nom : 'Moi',
    role:       'Geniwork Member',
    verified:   false,
    at:         Date.now(),
    time:       'À l\'instant',
    text:       text,
    images:     _imagesSnapshot,               /* base64 pour affichage immédiat */
    video:      videoData,
    doc:        docData,
    baseLikes:  0,
    likers:     [],
    comments:   [],
    ownerEmail: _currentUser ? _currentUser.email : null,
    tags:       _gwGetPendingTags(document.getElementById('pub-text')).slice(),
    type:       quoteData ? 'repost' : undefined,
    repostOf:   quoteData || undefined
  };

  /* Sauvegarde les blobs dans IndexedDB pour persistance */
  if (videoBlob && videoIdbId) { _gwSaveVideoBlob(videoIdbId, videoBlob, function() {}); }
  if (docBlob   && docIdbId)   { _gwSaveDocBlob(docIdbId, docBlob, function() {}); }

  /* Trace l'envoi en attente — si l'app est fermée pendant l'envoi de la vidéo,
     elle sera proposée à nouveau (bouton Réessayer) au prochain lancement, car
     la vidéo est déjà en sécurité dans IndexedDB. */
  if (_currentUser && videoBlob) {
    _gwAddPendingPost(_currentUser.email, JSON.parse(JSON.stringify(newPost)));
  }

  /* ── Scan NSFW sur données LOCALES (base64/blob) — avant tout upload ──
     On scanne _imagesSnapshot (base64) + vidéo locale pour éviter les
     problèmes CORS des URLs Firebase Storage.
     IMPORTANT : _nsfwGate résout seulement APRÈS le scan — l'upload vers
     Storage/Firebase (ce qui rend le post visible aux autres utilisateurs)
     attend ce résultat au lieu de partir en parallèle. Avant ce correctif,
     le scan (jusqu'à 30s, voir _gwAnalyzeVideoFrame) pouvait résoudre APRÈS
     que le Short soit déjà publié et visible pour tous, puis le supprimer
     de Firebase d'un coup — ce qui donnait l'impression que la vidéo
     "disparaissait" après coup. En cas d'erreur du scan on résout à `true`
     (fail-open) pour ne pas bloquer une publication légitime, comme avant. */
  var _nsfwGate;
  if (_imagesSnapshot.length > 0 || (_pickedVideo && _pickedVideo.url)) {
    var _nsfw_pid   = postId;
    var _nsfw_imgs  = _imagesSnapshot.slice();
    var _nsfw_vid   = (_pickedVideo && _pickedVideo.url) ? _pickedVideo.url : '';
    if (videoBlob) _showVideoProgress(0, 'Analyse du contenu…');
    else showToast('🔍 Analyse du contenu en cours…', 'info');
    _nsfwGate = _gwScanPostMedia(_nsfw_imgs, _nsfw_vid).then(function(result) {
      if (result && result.flagged) {
        _gwHandleNsfwDetection(result, String(_nsfw_pid));
        return false;
      }
      return true;
    }).catch(function(e) { console.warn('[GW] NSFW scan error', e); return true; });
  } else {
    _nsfwGate = Promise.resolve(true);
  }

  /* Affichage immédiat local avec les base64 */
  DEMO_POSTS.unshift(newPost);
  /* Protège ce post contre toute suppression Firebase pendant 60s */
  _gwRecentlyPublished[String(newPost.id)] = Date.now();

  /* ── Sauvegarde immédiate en localStorage (AVANT tout async) ──
     Skeleton sans base64 pour éviter QuotaExceededError.
     _finalizePost mettra à jour avec les vraies URLs via _gwPostUpsert. */
  try {
    var _skelPost = JSON.parse(JSON.stringify(newPost));
    if (_skelPost.images && _skelPost.images.length > 0) { _skelPost.images = []; }
    _gwPostUpsert(_skelPost);
  } catch(e) {}

  /* Succès confirmé dès que le post est en mémoire locale — avant tout appel
     qui pourrait jeter (renderFeed, notifyTags…) afin d'éviter le faux positif
     "Erreur lors de la publication" dans le catch extérieur. */
  showToast('Publication partagée ✓', 'ok');
  _unlockPubBtn();

  try {
    /* Cache le blob URL du Short pour lecture immédiate dans le player (session courante) */
    if (_pickedVideo && _pickedVideo.url && _pickedVideo.videoType === 'short') {
      _gwVidBlobCache[String(postId)] = _pickedVideo.url;
    }
    if (_currentUser) _incDailyCount('posts', _currentUser.email);
    renderFeed(_getFeedPosts());
    if (_currentUser) _gwNotifyTags(newPost.tags, newPost.id, _currentUser);
    _gwSaveHashtags(text);
    var _pubTextEl = document.getElementById('pub-text');
    if (_pubTextEl) _pubTextEl._gwPendingTags = [];
  } catch(_renderErr) {
    console.warn('[GW] Rendu feed post-publish (non-critique) :', _renderErr && _renderErr.message);
  }

  /* ── Upload médias vers Firebase Storage puis sauvegarde définitive ── */
  function _finalizePost(finalImages, finalVideoUrl, finalDocUrl) {
   try {
    /* ── Sécurité NSFW : si ce post a été bloqué par le scan, ne JAMAIS l'écrire dans Firebase ── */
    if (_gwNsfwBlockedPosts[String(newPost.id)]) {
      console.warn('[GW-NSFW] _finalizePost ignoré — post bloqué pour nudité', newPost.id);
      return;
    }
    /* Note : si l'upload vidéo a échoué (finalVideoUrl null), le toast d'erreur a déjà
       été affiché par le callback onFail de _uploadBlobToStorage. On continue ici pour
       sauvegarder les métadonnées dans Firebase (idbId seulement) afin que
       _gwUploadPendingVideos puisse ré-uploader automatiquement au prochain démarrage. */
    newPost.images = finalImages;
    var postToStore = JSON.parse(JSON.stringify(newPost));
    if (postToStore.video) {
      if (finalVideoUrl) {
        postToStore.video.url = finalVideoUrl;
        if (newPost.video) newPost.video.url = finalVideoUrl;
      } else {
        delete postToStore.video.url;
      }
      /* Propager cloudflareVideoId, storageProvider et videoStatus depuis newPost →
         postToStore. Ces champs sont posés dans onSuccess/onFail de _cfUploadVideo
         et doivent être persistés dans localStorage + Firebase via persistNewPost. */
      if (newPost.video) {
        if (newPost.video.cloudflareVideoId) {
          postToStore.video.cloudflareVideoId = newPost.video.cloudflareVideoId;
          postToStore.video.storageProvider   = 'cloudflare';
        }
        if (newPost.video.videoStatus) {
          postToStore.video.videoStatus = newPost.video.videoStatus;
        } else if (!finalVideoUrl) {
          postToStore.video.videoStatus = 'failed';
        }
      }
    }
    if (postToStore.doc) {
      if (finalDocUrl) {
        /* Upload réussi : URL Storage permanente accessible par tous les utilisateurs */
        postToStore.doc.url    = finalDocUrl;
        postToStore.doc.status = 'ready';
        if (newPost.doc) { newPost.doc.url = finalDocUrl; newPost.doc.status = 'ready'; }
        delete postToStore.doc.idbId; /* idbId inutile quand l'URL Storage est disponible */
      } else {
        /* Upload échoué : supprimer la blob URL (non sérialisable), garder l'idbId
           et storagePath pour que _gwUploadPendingDocs() puisse retenter au prochain démarrage */
        delete postToStore.doc.url;
        postToStore.doc.status = 'failed';
      }
    }
    persistNewPost(postToStore);
    var dp = DEMO_POSTS.find(function(p) { return p.id === newPost.id; });
    if (dp) {
      dp.images = finalImages;
      if (finalVideoUrl && dp.video) dp.video.url = finalVideoUrl;
      if (finalDocUrl   && dp.doc)   dp.doc.url   = finalDocUrl;
    }
    renderFeed(_getFeedPosts());
    if (_currentUser) _gwRemovePendingPost(_currentUser.email, newPost.id);
   } catch(_fpErr) {
     /* Ne JAMAIS laisser une exception ici passer inaperçue : sans ce filet, le post
        reste uploadé sur Storage/post_videos mais n'est jamais écrit dans gw/posts —
        il "disparaît" silencieusement pour tout le monde, y compris l'auteur au
        prochain démarrage (persistNewPost n'a jamais été appelé). */
     console.error('[GW] ❌ _finalizePost a échoué — post NON sauvegardé :', newPost.id, _fpErr);
     showToast('⚠️ Échec de la sauvegarde du post (' + (_fpErr && _fpErr.message || _fpErr) + ')', 'err');
   }
  }

  /* ── Attend confirmation de l'auth anonyme Firebase ET résultat du scan NSFW
     avant de lancer le véritable upload/publication (celui qui rend le post
     visible aux autres utilisateurs). Publier juste après l'ouverture de
     l'app (avant que signInAnonymously() ait résolu) faisait échouer les
     writes Firebase en silence (règles auth != null) — le post restait
     visible seulement en local pour l'auteur. _gwOnAuthReady a un filet de
     8s pour ne jamais bloquer indéfiniment si l'auth échoue durablement. ── */
  /* Barre de progression vidéo visible immédiatement (avant le scan NSFW et l'upload)
     pour que l'utilisateur sache que l'envoi est en cours dès le clic Publier */
  if (videoBlob) _showVideoProgress(0, 'Préparation de la vidéo…');

  _gwOnAuthReady(function() { _nsfwGate.then(function(_nsfwSafe) {
    if (!_nsfwSafe) { _hideVideoProgress(); return; } /* bloqué par le scan */

  var _hasImgOrDoc = (_imagesSnapshot.length > 0 || docBlob) && _gwFbStorage;
  if (videoBlob || _hasImgOrDoc) {
    var _pendingUploads   = (videoBlob ? 1 : 0) + (_imagesSnapshot.length > 0 && _gwFbStorage ? 1 : 0) + (docBlob && _gwFbStorage ? 1 : 0);
    var _uploadedImages   = _imagesSnapshot;
    var _uploadedVideoUrl = null;
    var _uploadedDocUrl   = null;

    function _onUploadDone() {
      if (--_pendingUploads <= 0) {
        _finalizePost(_uploadedImages, _uploadedVideoUrl, _uploadedDocUrl);
      }
    }

    if (_imagesSnapshot.length > 0 && _gwFbStorage) {
      _uploadImages('post_imgs/' + postId, _imagesSnapshot, function(urls) {
        _uploadedImages = urls;
        _onUploadDone();
      });
    }
    if (videoBlob) {
      function _doVidUpload(blobToUp) {
        _showVideoProgress(0, 'Envoi de la vidéo…');
        _cfUploadVideo(blobToUp, postId,
          function(pct) { _showVideoProgress(pct, 'Envoi de la vidéo…'); },
          function(url, cfMeta) {
            _uploadedVideoUrl = url;
            _gwVidUrlCache[postId] = url;
            try { localStorage.setItem('gw_vurl_' + postId, url); } catch(e2){}
            _showVideoProgress(100, 'Vidéo envoyée ✓');
            setTimeout(function() { _hideVideoProgress(); }, 800);
            /* Stocker cloudflareVideoId dans newPost.video AVANT _finalizePost —
               permet le retry idempotent si RTDB ou le post-write échoue ensuite */
            if (newPost.video && cfMeta && cfMeta.uid) {
              newPost.video.cloudflareVideoId = cfMeta.uid;
              newPost.video.storageProvider   = 'cloudflare';
              newPost.video.videoStatus       = 'ready';
            }
            /* Écriture gw/post_videos avec retry backoff (2s → 5s → 10s) */
            _gwPostVideoFbWriteWithRetry(postId, {
              url:       url,
              cfUid:     (cfMeta && cfMeta.uid)       || '',
              thumbnail: (cfMeta && cfMeta.thumbnail) || '',
              dur:       newPost.video ? (newPost.video.duration || 0) : 0
            }, 1);
            _onUploadDone();
          },
          function(e) {
            var _errCode = e && (e.code || e.message || String(e));
            _gwLog('VIDEO_UPLOAD_FAILED', { postId: String(postId), status: 'CF_ERROR', error: _errCode });
            showToast('⚠️ Vidéo non uploadée (' + (_errCode || 'inconnu') + ')', 'err');
            _hideVideoProgress();
            /* Marquer videoStatus 'failed' — inclus dans _finalizePost → persistNewPost */
            if (newPost.video) { newPost.video.videoStatus = 'failed'; }
            _onUploadDone();
          }
        );
      }
      /* La découpe a déjà été traitée dans l'éditeur — upload direct 0→100% */
      _doVidUpload(videoBlob);
    }
    if (docBlob && _gwFbStorage) {
      /* _docStoragePathSnapshot garantit que le retry utilisera exactement le même chemin */
      _uploadBlobToStorage(_docStoragePathSnapshot, docBlob,
        function(url) {
          _uploadedDocUrl = url;
          showToast('Document synchronisé ✓', 'ok');
          _onUploadDone();
        },
        function(e) {
          /* Échec upload — blob conservé en IndexedDB, status 'failed' posé par _finalizePost.
             _gwUploadPendingDocs() retentera au prochain démarrage avec le même storagePath. */
          _gwLog('DOC_UPLOAD_FAILED', {
            postId: String(postId),
            status: 'STORAGE_ERROR',
            error: e && (e.code || e.message || String(e)),
            extra: 'path=' + _docStoragePathSnapshot
          });
          showToast('⚠️ Document non synchronisé — sera renvoyé automatiquement', 'warn');
          _onUploadDone();
        }
      );
    }
  } else {
    _finalizePost(_imagesSnapshot, null, null);
  }

  }); });

  /* Réinitialise l'UI — erreurs ici non-critiques (post déjà soumis) */
  try {
    document.getElementById('pub-text').value = '';
    _clearQuoteRef();
    _pickedImages = [];
    renderImgPreviews();
    _pickedVideo = null;
    renderVideoPreview();
    _pickedDoc = null;
    renderDocPreview();
    document.getElementById('img-picker').value      = '';
    document.getElementById('cam-back-photo').value  = '';
    document.getElementById('cam-front-photo').value = '';
    document.getElementById('video-picker').value    = '';
    document.getElementById('cam-back-video').value  = '';
    document.getElementById('cam-front-video').value = '';
    var dp = document.getElementById('doc-picker');
    if (dp) dp.value = '';
    var homeBtn = document.querySelector('.bnav-item[data-page="p-home"]');
    navTo(homeBtn, 'p-home');
    var scroll = document.getElementById('feed-scroll');
    if (scroll) scroll.scrollTop = 0;
  } catch(_uiErr) {
    console.warn('[GW] Reset UI post-publish (non-critique) :', _uiErr && _uiErr.message);
  }

  } catch(err) {
    console.error('[GW] publierPost erreur :', err && (err.message || err));
    _unlockPubBtn();
    showToast('Erreur lors de la publication — réessayez', 'err');
  }
}

/* ancienne toggleSidebar supprimée — voir la nouvelle au-dessus */

/* ══════════════════════════════════════════
   NOTIFICATIONS — STOCKAGE PAR UTILISATEUR
══════════════════════════════════════════ */

/* Notification système unique pour tous (mise à jour appli) */
var SYSTEM_NOTIF = {
  id: 'sys-v1',
  type: 'system',
  fromUser: null,
  postId: null,
  postPreview: null,
  msg: '🎉 Bienvenue sur Geniwork v1.0 ! Nouvelles fonctionnalités bientôt disponibles.',
  at: Date.now() - 86400000 * 3,   /* simulé : il y a 3 jours */
  unread: false
};

function getNotifs(email) {
  var notifs = JSON.parse(localStorage.getItem('gw_notifs_' + email) || '[]');
  /* Rétrocompatibilité : ajoute `at` manquant sur les notifs déjà stockées */
  var needsSave = false;
  notifs.forEach(function(n) {
    if (!n.at) {
      /* L'ID numérique genNotifId() = Date.now() + random → > 1e12 = timestamp ms */
      n.at = (typeof n.id === 'number' && n.id > 1000000000000) ? Math.floor(n.id) : Date.now();
      needsSave = true;
    }
  });
  /* Persiste la correction pour ne pas recalculer avec Date.now() à chaque appel */
  if (needsSave) {
    try { localStorage.setItem('gw_notifs_' + email, JSON.stringify(notifs)); } catch(e) {}
  }
  return notifs;
}

function saveNotifs(email, notifs) {
  localStorage.setItem('gw_notifs_' + email, JSON.stringify(notifs));
  if (!_gwFbSkip) _gwFbSet('notifs/' + _gwFbKey(email), notifs);
}

function genNotifId() {
  return Date.now() + Math.floor(Math.random() * 1000);
}

/* ── Temps relatif réel pour les notifications ── */
function _notifTimeAgo(ts) {
  if (!ts || isNaN(ts)) return 'À l\'instant';
  var now     = Date.now();
  var diff    = Math.max(0, now - ts);          /* ms */
  var secs    = Math.floor(diff / 1000);
  var mins    = Math.floor(diff / 60000);
  var hours   = Math.floor(diff / 3600000);
  var days    = Math.floor(diff / 86400000);
  var weeks   = Math.floor(days / 7);
  var months  = Math.floor(days / 30);
  var years   = Math.floor(days / 365);

  if (secs  <  60)  return 'À l\'instant';
  if (mins  <  60)  return 'Il y a ' + mins  + ' min';
  if (hours <  24)  return 'Il y a ' + hours + (hours === 1 ? 'h' : 'h');
  if (days  === 1)  return 'Hier';
  if (days  <   7)  return 'Il y a ' + days  + ' jour' + (days > 1 ? 's' : '');
  if (weeks <   5)  return 'Il y a ' + weeks + ' semaine' + (weeks > 1 ? 's' : '');
  if (months < 12)  return 'Il y a ' + months + ' mois';
  return 'Il y a ' + years + ' an' + (years > 1 ? 's' : '');
}

/* Pousse une notification dans la liste d'un utilisateur cible */
function pushNotif(targetEmail, notif) {
  /* Horodatage automatique si absent */
  if (!notif.at) notif.at = Date.now();
  var notifs = getNotifs(targetEmail);
  notifs.unshift(notif);
  /* Limite à 50 notifications */
  if (notifs.length > 50) notifs = notifs.slice(0, 50);
  saveNotifs(targetEmail, notifs);
  /* Si c'est l'utilisateur courant, met à jour le badge en temps réel */
  if (_currentUser && targetEmail === _currentUser.email) {
    updateNotifBadge();
  }
  /* Push notification vers le destinataire s'il est sur un autre appareil */
  if (_currentUser && targetEmail !== _currentUser.email) {
    var _pTitle = notif.title || notif.label || 'Geniwork';
    var _pBody  = notif.body  || notif.text  || notif.msg || '';
    _gwSendPushNotif(targetEmail, _pTitle, _pBody, 'notif-' + _gwFbKey(targetEmail));
  }
}

/* seedDemoNotifs — supprimé (plus de données démo) */
function seedDemoNotifs(user) { /* no-op — kept for compat */ }

function renderNotifs() {
  if (!_currentUser) return;
  var list = document.getElementById('notifs-list');
  if (!list) return;

  var personal = getNotifs(_currentUser.email);
  /* Notification système toujours en dernier */
  var all = personal.concat([SYSTEM_NOTIF]);

  list.innerHTML = '';

  if (all.length === 0) {
    list.innerHTML = '<p style="text-align:center;color:#9CA3AF;padding:40px 16px;font-size:13px">Aucune notification pour l\'instant</p>';
    return;
  }

  all.forEach(function(n) {
    var item = document.createElement('div');
    item.className = 'notif-item' + (n.unread ? ' unread' : '');
    item.setAttribute('data-notif-id', String(n.id));

    var badgeCls  = getNotifBadgeCls(n.type);
    var badgeIcon = getNotifIcon(n.type);

    /* ── Avatar ── */
    var isGeniwork = !n.fromUser; /* Pas de fromUser = notification Geniwork officielle */
    var notifAvHtml, senderHtml;

    if (isGeniwork) {
      /* Logo officiel si disponible, sinon avatar Geniwork brandé */
      var gwLogo = _admGetOfficialLogo();
      if (gwLogo) {
        notifAvHtml =
          '<div class="notif-gw-av">' +
            '<img src="' + gwLogo + '" alt="Geniwork"/>' +
          '</div>';
      } else {
        notifAvHtml =
          '<div class="notif-gw-av notif-gw-av-default">' +
            '<i class="fas fa-star"></i>' +
          '</div>';
      }
      /* Badge vérifié bleu */
      senderHtml =
        '<div class="notif-gw-sender">' +
          'Geniwork' +
          '<span class="notif-gw-verified"><i class="fas fa-circle-check"></i></span>' +
        '</div>';
    } else {
      var notifDisplayName = getDisplayName(n.fromUser.email || null, n.fromUser.nom);
      notifAvHtml = getAvatarHtml(n.fromUser.email || null, notifDisplayName, 'sm');
      senderHtml  = '<strong>' + escHtml(notifDisplayName) + '</strong> ';
    }

    /* Tronquer le message si > 80 chars */
    var fullMsg   = n.msg || '';
    var isLong    = fullMsg.length > 80;
    var shortMsg  = isLong ? fullMsg.slice(0, 80) + '…' : fullMsg;

    item.innerHTML =
      '<div class="notif-av-wrap">' +
        notifAvHtml +
        '<div class="notif-type-badge ' + badgeCls + '"><i class="fas ' + badgeIcon + '"></i></div>' +
      '</div>' +
      '<div class="notif-body">' +
        '<div class="notif-msg">' +
          (isGeniwork ? senderHtml : senderHtml) +
          escHtml(isGeniwork ? shortMsg : shortMsg) +
        '</div>' +
        (n.postPreview ? '<div class="notif-preview">' + escHtml(n.postPreview) + '</div>' : '') +
        '<div class="notif-time-row">' +
          (n.unread ? '<span class="notif-unread-dot"></span>' : '') +
          '<span class="notif-time-txt">' + escHtml(_notifTimeAgo(n.at)) + '</span>' +
          (isLong ? '<span class="notif-read-more">Lire la suite</span>' : '') +
        '</div>' +
      '</div>' +
      '<i class="fas fa-chevron-right notif-chevron"></i>';

    /* Clic → toujours ouvrir le détail */
    (function(notif) {
      item.onclick = function() { openNotif(notif); };
    })(n);

    list.appendChild(item);
  });

  updateNotifBadge();
}

function updateNotifBadge() {
  var count = 0;
  if (_currentUser) {
    count = getNotifs(_currentUser.email).filter(function(n) { return n.unread; }).length;
  }
  var badge = document.getElementById('notif-badge');
  if (!badge) return;
  if (count > 0) {
    badge.textContent = count > 9 ? '9+' : count;
    badge.classList.remove('hidden');
  } else {
    badge.classList.add('hidden');
  }
}

function markAllRead() {
  if (!_currentUser) return;
  var notifs = getNotifs(_currentUser.email);
  notifs.forEach(function(n) { n.unread = false; });
  saveNotifs(_currentUser.email, notifs);
  renderNotifs();
  showToast('Toutes les notifications lues ✓', 'ok');
}

/* ── Ticker : met à jour les temps des notifs toutes les 60s si la page est ouverte ── */
(function() {
  setInterval(function() {
    var nPage = document.getElementById('p-notifs');
    if (!nPage || !nPage.classList.contains('active')) return;
    /* Met à jour uniquement les spans de temps sans re-rendre toute la liste */
    document.querySelectorAll('.notif-time-txt').forEach(function(span) {
      var item = span.closest('[data-notif-id]');
      if (!item) return;
      var nid = item.getAttribute('data-notif-id');
      if (!_currentUser) return;
      var notifs = getNotifs(_currentUser.email);
      var notif  = notifs.find(function(n) { return String(n.id) === String(nid); });
      if (notif && notif.at) span.textContent = _notifTimeAgo(notif.at);
    });
  }, 30000); /* toutes les 30 secondes */
})();

function getNotifIcon(type) {
  var icons = { like: 'fa-heart', comment: 'fa-comment', share: 'fa-share-nodes', follow: 'fa-user-plus', system: 'fa-bell', milestone: 'fa-trophy', bug_report: 'fa-bug', plan_limit: 'fa-lock', official: 'fa-bullhorn', artiste_approved: 'fa-microphone', artiste_copyright_notice: 'fa-scale-balanced', tag: 'fa-at', group_invite: 'fa-user-group' };
  return icons[type] || 'fa-bell';
}

function getNotifBadgeCls(type) {
  var cls = { like: 'nb-like', comment: 'nb-comment', share: 'nb-share', follow: 'nb-follow', system: 'nb-system', milestone: 'nb-milestone', bug_report: 'nb-system', plan_limit: 'nb-system', official: 'nb-system', artiste_approved: 'nb-milestone', artiste_copyright_notice: 'nb-system', tag: 'nb-tag', group_invite: 'nb-follow' };
  return cls[type] || 'nb-system';
}

/* ── Clic sur une notification → marquer lue + ouvrir détail ── */
function openNotif(notif) {
  /* Marque comme lue */
  if (_currentUser && notif.unread && notif.id !== 'sys-v1') {
    var notifs = getNotifs(_currentUser.email);
    var found  = notifs.find(function(x) { return x.id === notif.id; });
    if (found) { found.unread = false; saveNotifs(_currentUser.email, notifs); }
    var el = document.querySelector('[data-notif-id="' + notif.id + '"]');
    if (el) {
      el.classList.remove('unread');
      var dot = el.querySelector('.notif-unread-dot');
      if (dot) dot.remove();
    }
    updateNotifBadge();
  }
  /* Ouvre toujours la feuille de détail */
  _openNotifDetail(notif);
}

/* ── Feuille de détail complète d'une notification ── */
function _openNotifDetail(notif) {
  _closeGenericSheet('notif-detail');
  var isGeniwork = !notif.fromUser;
  var gwLogo     = _admGetOfficialLogo();
  var fullMsg    = notif.msg || '';

  /* Avatar + expéditeur */
  var avHtml, senderName, senderSub;
  if (isGeniwork) {
    avHtml = gwLogo
      ? '<div class="ndd-gw-av"><img src="' + gwLogo + '" alt="Geniwork"/></div>'
      : '<div class="ndd-gw-av ndd-gw-av-default"><i class="fas fa-star"></i></div>';
    senderName = 'Geniwork';
    senderSub  = 'Équipe officielle Geniwork';
  } else {
    var dName = getDisplayName(notif.fromUser.email || null, notif.fromUser.nom || '');
    avHtml     = getAvatarHtml(notif.fromUser.email || null, dName, 'lg');
    senderName = dName;
    senderSub  = notif.fromUser.email || '';
  }

  var bg = document.createElement('div');
  bg.className = 'notif-detail-bg';
  bg.id = 'notif-detail-bg';
  bg.onclick = function() { _closeGenericSheet('notif-detail'); };

  var card = document.createElement('div');
  card.className = 'notif-detail-card';
  card.id = 'notif-detail-card';
  card.innerHTML =
    '<div class="ndd-drag"></div>' +

    /* ─ En-tête expéditeur ─ */
    '<div class="ndd-header">' +
      '<div class="ndd-av-wrap">' +
        avHtml +
        (isGeniwork ? '<span class="ndd-gw-check"><i class="fas fa-circle-check"></i></span>' : '') +
      '</div>' +
      '<div class="ndd-sender-info">' +
        '<div class="ndd-sender-name">' +
          escHtml(senderName) +
          (isGeniwork ? '<span class="ndd-verified-chip"><i class="fas fa-circle-check"></i> Officiel</span>' : '') +
        '</div>' +
        '<div class="ndd-sender-sub">' + escHtml(senderSub) + '</div>' +
      '</div>' +
      '<div class="ndd-time">' + escHtml(_notifTimeAgo(notif.at)) + '</div>' +
    '</div>' +

    /* ─ Message complet ─ */
    '<div class="ndd-body">' +
      '<p class="ndd-msg">' + escHtml(fullMsg).replace(/\n/g, '<br>') + '</p>' +
      (notif.postPreview
        ? '<div class="ndd-preview-block"><i class="fas fa-quote-left ndd-quote"></i>' + escHtml(notif.postPreview) + '</div>'
        : '') +
    '</div>' +

    /* ─ Boutons d'action ─ */
    '<div class="ndd-actions">' +
      (notif.type === 'artiste_approved'
        ? '<button class="ndd-btn-primary" onclick="_closeGenericSheet(\'notif-detail\');setMkCat(\'artiste\');setTimeout(function(){_artisteOpenPublishForm();},300)">' +
            '<i class="fas fa-microphone"></i> Publier un son' +
          '</button>'
        : notif.type === 'group_invite' && notif.inviteToken
        ? '<button class="ndd-btn-primary" onclick="_closeGenericSheet(\'notif-detail\');_openGroupInviteScreen(\'' + String(notif.inviteToken).replace(/'/g,"") + '\')">' +
            '<i class="fas fa-user-group"></i> Voir l\'invitation' +
          '</button>'
        : notif.postId
          ? '<button class="ndd-btn-primary" onclick="_nddGoPost(' + notif.postId + ',\'' + (notif.type || '') + '\')">' +
              '<i class="fas fa-arrow-right"></i> Voir la publication' +
            '</button>'
          : (notif.fromUser
              ? (function(){
                  var _nEmail = (notif.fromUser.email||'').replace(/\\/g,'\\\\').replace(/'/g,"\\'");
                  var _nNom   = (notif.fromUser.nom  ||'').replace(/\\/g,'\\\\').replace(/'/g,"\\'");
                  var _nRole  = (notif.fromUser.role ||'').replace(/\\/g,'\\\\').replace(/'/g,"\\'");
                  return '<button class="ndd-btn-primary" onclick="_nddGoProfile(\'' + _nEmail + '\',\'' + _nNom + '\',\'' + _nRole + '\')">' +
                    '<i class="fas fa-user"></i> Voir le profil' +
                  '</button>';
                })()
              : '')) +
      '<button class="ndd-btn-secondary" onclick="_closeGenericSheet(\'notif-detail\')">Fermer</button>' +
    '</div>';

  document.body.appendChild(bg);
  document.body.appendChild(card);
  /* Double rAF : le navigateur doit peindre l'état initial (off-screen)
     avant d'ajouter 'open' pour que la transition CSS se déclenche */
  requestAnimationFrame(function() {
    requestAnimationFrame(function() {
      bg.classList.add('open');
      card.classList.add('open');
    });
  });
}

function _nddGoPost(postId, notifType) {
  _closeGenericSheet('notif-detail');

  /* Notification de commentaire → ouvre directement les commentaires (lisibles,
     pas juste le compteur) une fois la publication affichée */
  function _maybeOpenComments() {
    if (notifType === 'comment' || notifType === 'tag') {
      setTimeout(function() { try { openComments(postId); } catch(e) {} }, 350);
    }
  }

  /* Cherche le post dans le cache */
  var _targetPost = getAllPosts().find(function(p) { return String(p.id) === String(postId); });

  if (!_targetPost) {
    /* Publication officielle (post/vidéo/short Geniwork) — stockage séparé */
    var _offPost = _offGetPosts().find(function(p) { return String(p.id) === String(postId); });
    if (_offPost) {
      if (_offPost.video && _offPost.video.videoType === 'short') {
        try { openVideoScroll(postId); } catch(e) {}
      } else if (_offPost.video) {
        try { _openVideoClassic(_offPost, _offPost.video.duration || 0); } catch(e) {}
      } else {
        try { openOfficialProfile(); } catch(e) {}
      }
      _maybeOpenComments();
      return;
    }
    /* Pas encore chargé → attend 1,2s (Firebase sync) puis réessaie */
    showToast('Chargement de la publication…', 'info');
    setTimeout(function() {
      var p2 = getAllPosts().find(function(p) { return String(p.id) === String(postId); });
      if (p2) { _openPostQuickView(p2); _maybeOpenComments(); }
      else { showToast('Publication introuvable', 'warn'); }
    }, 1200);
    return;
  }

  if (_targetPost.video) {
    /* Vidéo → lecteur dédié */
    try { _openVideoFromPost(String(postId), _targetPost.video.duration || 0); } catch(e) {}
    _maybeOpenComments();
    return;
  }

  /* Image / texte → bottom-sheet rapide */
  _openPostQuickView(_targetPost);
  _maybeOpenComments();
}

/* ── Affiche un post dans un overlay bottom-sheet ── */
function _openPostQuickView(post) {
  /* Ferme un éventuel quickview déjà ouvert */
  var _old = document.getElementById('gw-post-qv-bg');
  if (_old) _old.remove();
  var _oldC = document.getElementById('gw-post-qv-modal');
  if (_oldC) _oldC.remove();

  /* Construit la carte du post */
  var cardEl;
  try { cardEl = buildPostCard(post); } catch(e) { showToast('Impossible d\'afficher la publication', 'warn'); return; }

  /* Fond semi-transparent */
  var bg = document.createElement('div');
  bg.id = 'gw-post-qv-bg';
  bg.style.cssText = 'position:fixed;inset:0;z-index:850;background:rgba(0,0,0,.55);transition:opacity .25s';
  bg.style.opacity = '0';
  bg.onclick = function() { _closePostQuickView(); };

  /* Bottom-sheet */
  var modal = document.createElement('div');
  modal.id = 'gw-post-qv-modal';
  modal.style.cssText = [
    'position:fixed;bottom:0;left:0;right:0;z-index:851',
    'background:#F8FAFC;border-radius:22px 22px 0 0',
    'max-height:88vh;overflow-y:auto',
    'padding:0 0 28px',
    'transform:translateY(100%);transition:transform .3s cubic-bezier(.32,.72,0,1)',
    'max-width:640px;margin:0 auto'
  ].join(';');

  /* En-tête avec poignée + titre + bouton fermer */
  var header = document.createElement('div');
  header.style.cssText = 'position:sticky;top:0;background:#F8FAFC;z-index:1;padding:10px 16px 8px;border-bottom:1px solid #F1F5F9';
  header.innerHTML =
    '<div style="width:36px;height:4px;background:#CBD5E1;border-radius:4px;margin:0 auto 10px"></div>' +
    '<div style="display:flex;align-items:center;justify-content:space-between">' +
      '<span style="font-size:14px;font-weight:700;color:#0F172A">Publication</span>' +
      '<button onclick="_closePostQuickView()" style="background:#F1F5F9;border:none;width:30px;height:30px;border-radius:50%;font-size:15px;color:#64748B;cursor:pointer;display:flex;align-items:center;justify-content:center">' +
        '<i class="fas fa-times"></i>' +
      '</button>' +
    '</div>';

  /* Wrapper de la carte — désactive l'ID pour éviter les doublons avec le feed */
  cardEl.style.margin = '0';
  cardEl.style.borderRadius = '0';
  cardEl.style.boxShadow = 'none';

  modal.appendChild(header);
  modal.appendChild(cardEl);

  document.body.appendChild(bg);
  document.body.appendChild(modal);

  /* Animation d'entrée */
  requestAnimationFrame(function() {
    requestAnimationFrame(function() {
      bg.style.opacity = '1';
      modal.style.transform = 'translateY(0)';
    });
  });

  /* Initialise les vidéos dans la carte si présentes */
  try { _initFeedVideoObserver(); } catch(e){}
}

function _closePostQuickView() {
  var bg    = document.getElementById('gw-post-qv-bg');
  var modal = document.getElementById('gw-post-qv-modal');
  if (bg)    bg.style.opacity = '0';
  if (modal) modal.style.transform = 'translateY(100%)';
  setTimeout(function() {
    if (bg)    bg.remove();
    if (modal) modal.remove();
  }, 320);
}
function _nddGoProfile(email, nom, role) {
  _closeGenericSheet('notif-detail');
  openUserProfile({ email: email || null, nom: nom || '', role: role || '' });
}

/* Flash d'un post dans le feed */
function highlightPost(postId) {
  var card = document.getElementById('post-' + postId);
  if (!card) { showToast('Publication introuvable', 'warn'); return; }
  card.scrollIntoView({ behavior: 'smooth', block: 'center' });
  card.classList.remove('post-highlight');
  void card.offsetWidth; /* reflow pour relancer l'animation */
  card.classList.add('post-highlight');
  setTimeout(function() { card.classList.remove('post-highlight'); }, 2200);
}

/* Redirige l'ancienne API (notifications etc.) vers la vue complète */
function openUserProfile(userInfo) {
  openUserProfileView(userInfo);
}
function closeProfileModal() { /* compat — no-op */ }

/* ══════════════════════════════════════════
   PROFIL UTILISATEUR
══════════════════════════════════════════ */

/* ── Storage ── */
/* ── Cache mémoire profils (évite JSON.parse localStorage répété) ── */
var _profileCache = {};
function _invalidateProfileCache(email) { if (email) delete _profileCache[email]; }

function loadUserProfile(email) {
  if (!email) return null;
  if (_profileCache[email] !== undefined) return _profileCache[email];
  var profile = JSON.parse(localStorage.getItem('gw_profile_' + email) || 'null');
  /* Restauration automatique depuis la sauvegarde dédiée si la photo manque */
  if (profile && !profile.photo) {
    var _backupPhoto = localStorage.getItem('gw_photo_' + email);
    if (_backupPhoto) { profile.photo = _backupPhoto; }
  }
  _profileCache[email] = profile;
  return profile;
}

/* ── Pousse le profil vers Firebase avec compression photo automatique ──────
   La photo est toujours incluse : si elle est > 150 Ko, elle est compressée
   de façon asynchrone avant l'écriture. Plus jamais de photo supprimée.     */
function _pushProfileToFirebase(email, data) {
  if (!_gwFbReady || !_gwFbDB) return;
  var ref  = _gwFbDB.ref('gw/profiles/' + _gwFbKey(email));
  var copy = Object.assign({}, data);
  /* Pas de photo ou photo déjà petite → écriture directe */
  if (!copy.photo || copy.photo.length <= 150000) {
    ref.set(copy).catch(function(){});
    return;
  }
  /* Photo trop grande → compression asynchrone (max 150 Ko) puis écriture */
  _compressImageForChat(copy.photo, 150000, function(compressed) {
    copy.photo = compressed;
    ref.set(copy).catch(function(){});
  });
}

function saveUserProfile(email, data) {
  _invalidateProfileCache(email); /* invalide le cache mémoire */
  var ts = Date.now();
  var saved = false;
  try {
    localStorage.setItem('gw_profile_' + email, JSON.stringify(data));
    saved = true;
  } catch(e) {
    /* QuotaExceededError : re-tente sans la photo */
    if (data && data.photo) {
      try {
        localStorage.setItem('gw_profile_' + email, JSON.stringify(Object.assign({}, data, { photo: null })));
        saved = true;
      } catch(e2) {}
    }
    showToast('Espace de stockage insuffisant — essayez une photo plus petite.', 'err');
  }
  /* Sauvegarde dédiée de la photo — survit aux QuotaExceededError sur le profil complet */
  if (data && data.photo) {
    try { localStorage.setItem('gw_photo_' + email, data.photo); } catch(e4) {}
  }
  /* Signal global — écrit une seule fois après la sauvegarde réussie */
  if (saved) {
    try { localStorage.setItem('gw_profile_changed', JSON.stringify({ email: email, at: ts })); } catch(e3) {}
    /* ── Sync Firebase profil (avec compression photo automatique) ── */
    if (!_gwFbSkip) {
      _pushProfileToFirebase(email, data);
    }
  }
}
function getDefaultProfile(user) {
  var now = new Date();
  var month = now.toLocaleDateString('fr-FR', { month: 'long', year: 'numeric' });
  return {
    photo: null,
    nom: user.nom,
    domain: '',
    location: '',
    bio: '',
    skills: [],
    memberSince: month,
    projects: 0,
    rating: null,
    followers: 0,
    following: 0
  };
}

/* ── Rendu de la page profil ── */
function renderProfilePage() {
  if (!_currentUser) return;
  var profile = loadUserProfile(_currentUser.email) || getDefaultProfile(_currentUser);

  _renderCollabInvitesBanner();

  /* Photo */
  var photoImg      = document.getElementById('profil-photo-img');
  var photoInitials = document.getElementById('profil-photo-initials');
  if (photoImg && photoInitials) {
    if (profile.photo) {
      photoImg.src          = profile.photo;
      photoImg.style.display = 'block';
      photoInitials.style.display = 'none';
    } else {
      photoImg.style.display      = 'none';
      photoInitials.style.display = '';
      photoInitials.textContent   = getInitials(profile.nom || _currentUser.nom);
    }
  }

  /* Nom */
  var nameEl = document.getElementById('profil-name-display');
  if (nameEl) nameEl.textContent = profile.nom || _currentUser.nom;

  /* Badge */
  var badgeDisplayEl = document.getElementById('profil-badge-display');
  if (badgeDisplayEl) badgeDisplayEl.innerHTML = getBadgeHtml(_currentUser.email);

  /* Domaine */
  var domEl = document.getElementById('profil-domain-display');
  if (domEl) domEl.textContent = profile.domain || 'Ajouter votre domaine';

  /* Localisation */
  var locEl = document.getElementById('profil-location-text');
  if (locEl) locEl.textContent = profile.location || 'Ajouter une ville';

  /* Stats */
  var setTxt = function(id, v) { var el = document.getElementById(id); if (el) el.textContent = v; };
  var _selfKey = getProfileKey({ nom: _currentUser.nom, email: _currentUser.email });
  setTxt('pstat-projects',  loadProjects(_currentUser.email).length);
  setTxt('pstat-rating',    profile.rating ? profile.rating + ' ★' : '—');
  setTxt('pstat-followers', _getTotalFollowers(_selfKey, false));  /* toujours depuis le vrai storage */
  setTxt('pstat-following', getFollowing().length);

  /* Bio */
  var bioEl = document.getElementById('profil-bio-display');
  if (bioEl) {
    if (profile.bio) {
      bioEl.textContent = profile.bio;
      bioEl.classList.remove('empty-bio');
    } else {
      bioEl.textContent = 'Aucune description. Appuyez sur le crayon pour vous présenter.';
      bioEl.classList.add('empty-bio');
    }
  }

  /* Membre depuis */
  var memberEl = document.getElementById('profil-member-since');
  if (memberEl) memberEl.textContent = 'Membre depuis ' + (profile.memberSince || 'récemment');

  /* Compétences */
  _renderProfileSkills(profile.skills || []);

  /* Bouton badge CTA sous le nom */
  var badgeCta = document.getElementById('profil-badge-cta');
  if (badgeCta) {
    if (profile.badgeType === 'certified') {
      badgeCta.style.display = 'inline-flex';
      badgeCta.innerHTML = '<i class="fas fa-circle-check"></i> Compte certifié';
      badgeCta.className = 'profil-badge-cta';
      badgeCta.style.background = 'linear-gradient(135deg,#16A34A,#15803D)';
      badgeCta.style.color = '#fff';
      badgeCta.style.cursor = 'default';
      badgeCta.onclick = null;
    } else if (profile.badgeType === 'verified') {
      badgeCta.style.display = 'inline-flex';
      badgeCta.innerHTML = '<i class="fas fa-circle-check"></i> Badge Vérifié';
      badgeCta.className = 'profil-badge-cta profil-badge-cta-blue';
      badgeCta.style.background = ''; badgeCta.style.color = ''; badgeCta.style.cursor = '';
    } else if (profile.badgeType === 'premium') {
      badgeCta.style.display = 'inline-flex';
      badgeCta.innerHTML = '<i class="fas fa-crown"></i> Badge Premium';
      badgeCta.className = 'profil-badge-cta profil-badge-cta-gold';
      badgeCta.style.background = ''; badgeCta.style.color = ''; badgeCta.style.cursor = '';
    } else if (profile.badgeStatus === 'pending') {
      badgeCta.style.display = 'inline-flex';
      badgeCta.innerHTML = '<i class="fas fa-hourglass-half"></i> Vérification en cours…';
      badgeCta.className = 'profil-badge-cta profil-badge-cta-pending';
      badgeCta.style.background = ''; badgeCta.style.color = ''; badgeCta.style.cursor = '';
    } else {
      badgeCta.style.display = 'inline-flex';
      badgeCta.innerHTML = '<i class="fas fa-shield-halved"></i> Obtenir le badge';
      badgeCta.className = 'profil-badge-cta profil-badge-cta-default';
    }
  }

  /* ── Téléphone ── */
  var phoneValEl  = document.getElementById('profil-phone-display');
  var phoneVerEl  = document.getElementById('profil-phone-verified');
  var phoneVisBadge = document.getElementById('profil-phone-vis-badge');
  if (phoneValEl) {
    phoneValEl.textContent = profile.phone || 'Ajouter un numéro';
    phoneValEl.style.color = profile.phone ? '#111827' : '#9CA3AF';
  }
  if (phoneVerEl) {
    phoneVerEl.style.display = profile.phoneVerified ? 'inline' : 'none';
  }
  if (phoneVisBadge) {
    if (profile.phonePublic) {
      phoneVisBadge.innerHTML = '<i class="fas fa-earth-europe"></i> Public';
      phoneVisBadge.className = 'profil-visibility-badge profil-vis-public';
    } else {
      phoneVisBadge.innerHTML = '<i class="fas fa-lock"></i> Privé';
      phoneVisBadge.className = 'profil-visibility-badge';
    }
  }

  /* ── Email professionnel ── */
  var emailValEl    = document.getElementById('profil-email-display');
  var emailVisBadge = document.getElementById('profil-email-vis-badge');
  var cooldownInfo  = _getProEmailCooldownInfo(profile);

  if (emailValEl) {
    if (profile.proEmail) {
      emailValEl.textContent = profile.proEmail;
      emailValEl.style.color = '#111827';
    } else {
      emailValEl.textContent = 'Ajouter un email pro';
      emailValEl.style.color = '#9CA3AF';
    }
    /* Indicateur de cooldown actif sur la ligne */
    var emailRow = document.getElementById('profil-email-row');
    if (emailRow) {
      var oldCooldownBadge = emailRow.querySelector('.pro-email-mini-cd');
      if (oldCooldownBadge) oldCooldownBadge.remove();
      if (cooldownInfo.locked && profile.proEmail) {
        var cdBadge = document.createElement('span');
        cdBadge.className = 'pro-email-mini-cd';
        cdBadge.innerHTML = '<i class="fas fa-clock"></i> ' + cooldownInfo.daysLeft + 'j';
        emailValEl.parentNode.appendChild(cdBadge);
      }
    }
  }
  if (emailVisBadge) {
    if (profile.proEmailPublic) {
      emailVisBadge.innerHTML = '<i class="fas fa-earth-europe"></i> Public';
      emailVisBadge.className = 'profil-visibility-badge profil-vis-public';
    } else {
      emailVisBadge.innerHTML = '<i class="fas fa-lock"></i> Privé';
      emailVisBadge.className = 'profil-visibility-badge';
    }
  }

  /* Badge "Compte Google" — masqué */
  var googleBadge = document.getElementById('profil-google-badge');
  if (googleBadge) googleBadge.style.display = 'none';
}

function _renderProfileSkills(skills) {
  var wrap = document.getElementById('profil-skills-display');
  if (!wrap) return;
  if (!skills.length) {
    wrap.innerHTML = '<p class="profil-empty-hint">Aucune compétence. Appuyez sur le crayon pour en ajouter.</p>';
    return;
  }
  wrap.innerHTML = skills.map(function(s) {
    return '<span class="profil-skill-chip">' + escHtml(s) + '</span>';
  }).join('');
}

/* ── Switcher de tabs ── */
function switchProfilTab(btn, tab) {
  /* Uniquement les tabs du profil courant (pas ceux de user-profile-view) */
  document.querySelectorAll('#p-profil .profil-tab').forEach(function(b) { b.classList.remove('active'); });
  btn.classList.add('active');
  var map = { about: 'ptab-about', services: 'ptab-services', projects: 'ptab-projects', reviews: 'ptab-reviews', posts: 'ptab-posts' };
  Object.values(map).forEach(function(id) {
    var el = document.getElementById(id);
    if (el) el.classList.add('hidden');
  });
  var target = document.getElementById(map[tab]);
  if (target) target.classList.remove('hidden');
  /* Rend les publications si l'onglet est sélectionné */
  if (tab === 'posts' && _currentUser) {
    renderProfilPosts(_currentUser.email, _currentUser.nom, target);
  }
  if (tab === 'services')  renderProfileServices();
  if (tab === 'projects')  renderProfileProjects();
}

/* ── Photo de profil ── */
function pickProfilePhoto() {
  var inp = document.getElementById('profil-photo-picker');
  if (inp) inp.click();
}

function handleProfilePhoto(input) {
  if (!input.files || !input.files[0]) return;
  var reader = new FileReader();
  reader.onload = function(e) { _openCropModal(e.target.result); };
  reader.readAsDataURL(input.files[0]);
  input.value = '';
}

/* ══════════════════════════════════════════
   RECADRAGE GÉNÉRIQUE — photos marketplace / services / ebook
   File d'attente : traite chaque photo sélectionnée une par une dans
   la fenêtre de recadrage avant de l'ajouter à la liste de l'appelant.
══════════════════════════════════════════ */
var _rcSrcImg          = null;
var _rcScale           = 1;
var _rcX               = 0;
var _rcY               = 0;
var _rcVW              = 280;
var _rcVH              = 280;
var _rcOutW            = 800;
var _rcOutH            = 800;
var _rcQueue           = [];
var _gwRectCropDone    = null;
var _gwRectCropCancelFn = null;

/* files: FileList/array de File · aspectW/aspectH: ratio du cadre (1,1 = carré)
   onEach(dataUrl) est appelé à chaque photo validée */
function _gwQueueImageCrop(files, aspectW, aspectH, onEach) {
  var arr = Array.prototype.slice.call(files);
  if (!arr.length) return;
  _rcQueue = arr;
  _gwProcessNextCropInQueue(aspectW, aspectH, onEach);
}

function _gwProcessNextCropInQueue(aspectW, aspectH, onEach) {
  if (!_rcQueue.length) return;
  var file = _rcQueue.shift();
  var reader = new FileReader();
  reader.onload = function(e) {
    _gwOpenRectCrop(e.target.result, aspectW, aspectH,
      function(dataUrl) { onEach(dataUrl); _gwProcessNextCropInQueue(aspectW, aspectH, onEach); },
      function()         { _gwProcessNextCropInQueue(aspectW, aspectH, onEach); }
    );
  };
  reader.readAsDataURL(file);
}

function _gwOpenRectCrop(src, aspectW, aspectH, onDone, onCancel) {
  var modal = document.getElementById('gw-rect-crop-modal');
  var imgEl = document.getElementById('gw-rect-crop-img');
  var range = document.getElementById('gw-rect-crop-zoom');
  var vp    = document.getElementById('gw-rect-crop-viewport');
  if (!modal || !imgEl || !range || !vp) { if (onDone) onDone(src); return; }

  /* La modale vit dans #screen-app, qui a son propre z-index (contexte d'empilement isolé,
     voir .screen en CSS) — elle ne peut donc jamais passer au-dessus des panneaux ajoutés
     directement à <body> (formulaires marketplace, services, etc.). On la déplace sous
     <body> pour qu'elle s'affiche toujours au-dessus, quel que soit l'écran ouvert. */
  if (modal.parentNode !== document.body) document.body.appendChild(modal);

  /* Dimensionne le cadre selon le ratio demandé (largeur fixe, hauteur proportionnelle) */
  var W = 280, H = Math.round(W * (aspectH / aspectW));
  var MAXH = 380;
  if (H > MAXH) { H = MAXH; W = Math.round(H * (aspectW / aspectH)); }
  _rcVW = W; _rcVH = H;
  vp.style.width  = W + 'px';
  vp.style.height = H + 'px';

  _rcOutW = 800;
  _rcOutH = Math.round(800 * (aspectH / aspectW));

  _gwRectCropDone     = onDone;
  _gwRectCropCancelFn = onCancel;

  _rcSrcImg = new Image();
  _rcSrcImg.onload = function() {
    /* Échelle initiale : l'image recouvre tout le cadre (pas de bord vide) */
    var scaleW = _rcVW / _rcSrcImg.naturalWidth;
    var scaleH = _rcVH / _rcSrcImg.naturalHeight;
    _rcScale = Math.max(scaleW, scaleH);
    _rcX = (_rcVW - _rcSrcImg.naturalWidth  * _rcScale) / 2;
    _rcY = (_rcVH - _rcSrcImg.naturalHeight * _rcScale) / 2;
    _rcApplyTransform(imgEl);

    range.min   = _rcScale.toFixed(4);
    range.max   = (_rcScale * 5).toFixed(4);
    range.step  = '0.01';
    range.value = _rcScale;

    _rcAttachEvents(imgEl, range);
  };
  _rcSrcImg.src = src;
  imgEl.src = src;
  modal.style.display = 'flex';
}

function _rcApplyTransform(imgEl) {
  imgEl.style.transform = 'translate(' + _rcX + 'px,' + _rcY + 'px) scale(' + _rcScale + ')';
}

/* Empêche l'image de se décoller du cadre (pas de bord vide, contrairement au crop circulaire) */
function _rcClamp() {
  var iw = _rcSrcImg.naturalWidth  * _rcScale;
  var ih = _rcSrcImg.naturalHeight * _rcScale;
  var minX = _rcVW - iw, minY = _rcVH - ih;
  if (_rcX > 0) _rcX = 0; if (_rcX < minX) _rcX = minX;
  if (_rcY > 0) _rcY = 0; if (_rcY < minY) _rcY = minY;
}

function _rcAttachEvents(imgEl, range) {
  var vp = document.getElementById('gw-rect-crop-viewport');
  vp.onmousedown = null; vp.ontouchstart = null;

  var isDragging = false, lastX = 0, lastY = 0;
  var pinchStartDist = 0, pinchStartScale = 1;

  vp.onmousedown = function(e) {
    isDragging = true; lastX = e.clientX; lastY = e.clientY;
    imgEl.style.cursor = 'grabbing'; e.preventDefault();
  };
  document.onmousemove = function(e) {
    if (!isDragging) return;
    _rcX += e.clientX - lastX; _rcY += e.clientY - lastY;
    lastX = e.clientX; lastY = e.clientY;
    _rcClamp(); _rcApplyTransform(imgEl);
  };
  document.onmouseup = function() { isDragging = false; imgEl.style.cursor = 'grab'; };

  vp.ontouchstart = function(e) {
    e.preventDefault();
    if (e.touches.length === 1) {
      isDragging = true; lastX = e.touches[0].clientX; lastY = e.touches[0].clientY;
    } else if (e.touches.length === 2) {
      isDragging = false;
      pinchStartDist  = Math.hypot(
        e.touches[1].clientX - e.touches[0].clientX,
        e.touches[1].clientY - e.touches[0].clientY);
      pinchStartScale = _rcScale;
    }
  };
  vp.ontouchmove = function(e) {
    e.preventDefault();
    if (e.touches.length === 1 && isDragging) {
      _rcX += e.touches[0].clientX - lastX;
      _rcY += e.touches[0].clientY - lastY;
      lastX = e.touches[0].clientX; lastY = e.touches[0].clientY;
      _rcClamp(); _rcApplyTransform(imgEl);
    } else if (e.touches.length === 2) {
      var dist = Math.hypot(
        e.touches[1].clientX - e.touches[0].clientX,
        e.touches[1].clientY - e.touches[0].clientY);
      _rcSetScale(pinchStartScale * dist / pinchStartDist, imgEl, range);
    }
  };
  vp.ontouchend = function(e) { if (e.touches.length < 2) isDragging = false; };

  range.oninput = function() { _rcSetScale(parseFloat(range.value), imgEl, range); };
}

function _rcSetScale(newScale, imgEl, range) {
  var min = parseFloat(range.min), max = parseFloat(range.max);
  newScale = Math.max(min, Math.min(max, newScale));
  var ratio = newScale / _rcScale;
  var cx = _rcVW / 2, cy = _rcVH / 2;
  _rcX = cx - (cx - _rcX) * ratio;
  _rcY = cy - (cy - _rcY) * ratio;
  _rcScale = newScale;
  range.value = newScale;
  _rcClamp();
  _rcApplyTransform(imgEl);
}

function _gwRectCropApply() {
  if (!_rcSrcImg) return;
  var srcX = (0 - _rcX) / _rcScale;
  var srcY = (0 - _rcY) / _rcScale;
  var srcW = _rcVW / _rcScale;
  var srcH = _rcVH / _rcScale;

  var canvas = document.createElement('canvas');
  canvas.width = _rcOutW; canvas.height = _rcOutH;
  canvas.getContext('2d').drawImage(_rcSrcImg, srcX, srcY, srcW, srcH, 0, 0, _rcOutW, _rcOutH);
  var dataUrl = canvas.toDataURL('image/jpeg', 0.85);

  var done = _gwRectCropDone;
  _gwRectCropCancelInternal();
  if (done) done(dataUrl);
}

function _gwRectCropCancel() {
  var cancelFn = _gwRectCropCancelFn;
  _gwRectCropCancelInternal();
  if (cancelFn) cancelFn();
}

function _gwRectCropCancelInternal() {
  var modal = document.getElementById('gw-rect-crop-modal');
  if (modal) modal.style.display = 'none';
  document.onmousemove = null;
  document.onmouseup   = null;
  _rcSrcImg = null;
  _gwRectCropDone = null;
  _gwRectCropCancelFn = null;
}

/* ══════════════════════════════════════════
   CROP / RECADRAGE PHOTO DE PROFIL
══════════════════════════════════════════ */
var _cropSrcImg  = null;
var _cropScale   = 1;
var _cropX       = 0;
var _cropY       = 0;
var _cropVW      = 280;   /* largeur viewport */
var _cropVH      = 280;   /* hauteur viewport */
var _cropDia     = 240;   /* diamètre du cercle de recadrage */

function _openCropModal(src) {
  var modal  = document.getElementById('photo-crop-modal');
  var imgEl  = document.getElementById('crop-img-el');
  var range  = document.getElementById('crop-zoom-range');
  if (!modal || !imgEl || !range) return;

  _cropSrcImg = new Image();
  _cropSrcImg.onload = function() {
    /* Échelle initiale : le côté court remplit le cercle */
    var minSide = Math.min(_cropSrcImg.naturalWidth, _cropSrcImg.naturalHeight);
    _cropScale  = _cropDia / minSide;
    _cropX = (_cropVW - _cropSrcImg.naturalWidth  * _cropScale) / 2;
    _cropY = (_cropVH - _cropSrcImg.naturalHeight * _cropScale) / 2;
    _cropApplyTransform(imgEl);

    range.min   = _cropScale.toFixed(4);
    range.max   = (_cropScale * 5).toFixed(4);
    range.step  = '0.01';
    range.value = _cropScale;

    _cropAttachEvents(imgEl, range);
  };
  _cropSrcImg.src = src;
  imgEl.src = src;

  modal.style.display = 'flex';
}

function _cropApplyTransform(imgEl) {
  imgEl.style.transform =
    'translate(' + _cropX + 'px,' + _cropY + 'px) scale(' + _cropScale + ')';
}

function _cropAttachEvents(imgEl, range) {
  var vp = document.getElementById('crop-viewport');

  /* ── Nettoyage des anciens listeners ── */
  vp.onmousedown = null;
  vp.ontouchstart = null;

  var isDragging = false, lastX = 0, lastY = 0;
  var pinchStartDist = 0, pinchStartScale = 1;

  /* Mouse */
  vp.onmousedown = function(e) {
    isDragging = true; lastX = e.clientX; lastY = e.clientY;
    imgEl.style.cursor = 'grabbing'; e.preventDefault();
  };
  document.onmousemove = function(e) {
    if (!isDragging) return;
    _cropX += e.clientX - lastX; _cropY += e.clientY - lastY;
    lastX = e.clientX; lastY = e.clientY;
    _cropApplyTransform(imgEl);
  };
  document.onmouseup = function() {
    isDragging = false; imgEl.style.cursor = 'grab';
  };

  /* Touch — drag + pinch */
  vp.ontouchstart = function(e) {
    e.preventDefault();
    if (e.touches.length === 1) {
      isDragging = true;
      lastX = e.touches[0].clientX; lastY = e.touches[0].clientY;
    } else if (e.touches.length === 2) {
      isDragging = false;
      pinchStartDist  = Math.hypot(
        e.touches[1].clientX - e.touches[0].clientX,
        e.touches[1].clientY - e.touches[0].clientY);
      pinchStartScale = _cropScale;
    }
  };
  vp.ontouchmove = function(e) {
    e.preventDefault();
    if (e.touches.length === 1 && isDragging) {
      _cropX += e.touches[0].clientX - lastX;
      _cropY += e.touches[0].clientY - lastY;
      lastX = e.touches[0].clientX; lastY = e.touches[0].clientY;
      _cropApplyTransform(imgEl);
    } else if (e.touches.length === 2) {
      var dist = Math.hypot(
        e.touches[1].clientX - e.touches[0].clientX,
        e.touches[1].clientY - e.touches[0].clientY);
      _cropSetScale(pinchStartScale * dist / pinchStartDist, imgEl, range);
    }
  };
  vp.ontouchend = function(e) { if (e.touches.length < 2) isDragging = false; };

  /* Slider */
  range.oninput = function() {
    _cropSetScale(parseFloat(range.value), imgEl, range);
  };
}

function _cropSetScale(newScale, imgEl, range) {
  var min = parseFloat(range.min), max = parseFloat(range.max);
  newScale = Math.max(min, Math.min(max, newScale));
  var ratio = newScale / _cropScale;
  var cx = _cropVW / 2, cy = _cropVH / 2;
  /* Zoom centré sur le centre du viewport */
  _cropX = cx - (cx - _cropX) * ratio;
  _cropY = cy - (cy - _cropY) * ratio;
  _cropScale = newScale;
  range.value = newScale;
  _cropApplyTransform(imgEl);
}

function _cropApply() {
  if (!_cropSrcImg) return;
  var r       = _cropDia / 2;
  var cx      = _cropVW / 2, cy = _cropVH / 2;
  /* Coordonnées dans l'image source correspondant au cercle */
  var srcX = (cx - r - _cropX) / _cropScale;
  var srcY = (cy - r - _cropY) / _cropScale;
  var srcW = _cropDia / _cropScale;

  var OUT  = 180;
  var canvas = document.createElement('canvas');
  canvas.width = OUT; canvas.height = OUT;
  var ctx = canvas.getContext('2d');
  ctx.drawImage(_cropSrcImg, srcX, srcY, srcW, srcW, 0, 0, OUT, OUT);

  var dataUrl = canvas.toDataURL('image/jpeg', 0.72);

  var profile = loadUserProfile(_currentUser.email) || getDefaultProfile(_currentUser);

  function _applyPhoto(src) {
    profile.photo = src;
    profile._googlePhoto = false;  /* photo perso → jamais écrasée par _importGooglePhoto */
    saveUserProfile(_currentUser.email, profile);
    _onProfileSaved();
    showToast('Photo de profil mise à jour ✓', 'ok');
    _cropCancel();
  }

  if (_gwFbStorage) {
    /* Upload vers Firebase Storage → URL permanente sur tous les appareils */
    showToast('Upload photo…', '');
    _uploadToStorage('photos/' + _gwFbKey(_currentUser.email) + '.jpg', dataUrl,
      function(url) { _applyPhoto(url); },
      function()    { _applyPhoto(dataUrl); }   /* fallback base64 si upload échoue */
    );
  } else {
    _applyPhoto(dataUrl);
  }
}

function _cropCancel() {
  var modal = document.getElementById('photo-crop-modal');
  if (modal) modal.style.display = 'none';
  document.onmousemove = null;
  document.onmouseup  = null;
  _cropSrcImg = null;
}

/* ── Paramètres du profil (hub d'édition) ── */
function openProfileSettings() {
  _closeGenericSheet('profil-settings');
  var profile = loadUserProfile(_currentUser.email) || getDefaultProfile(_currentUser);

  var bg = document.createElement('div');
  bg.className = 'cam-sheet-bg'; bg.id = 'profil-settings-bg';
  bg.onclick = function() { _closeGenericSheet('profil-settings'); };

  var card = document.createElement('div');
  card.className = 'cam-sheet-card'; card.id = 'profil-settings-card';
  card.innerHTML =
    '<div class="cam-sheet-handle"></div>' +
    '<p class="cam-sheet-title">Modifier le profil</p>' +

    '<button class="cam-sheet-btn" onclick="_closeGenericSheet(\'profil-settings\');openEditName()">' +
      '<div class="cam-sheet-icon" style="background:#EFF6FF;color:#2563EB"><i class="fas fa-user-pen"></i></div>' +
      '<div class="cam-sheet-label"><strong>Nom complet</strong>' +
        '<small>' + escHtml(profile.nom || '') + '</small></div>' +
    '</button>' +

    '<button class="cam-sheet-btn" onclick="_closeGenericSheet(\'profil-settings\');openEditDomain()">' +
      '<div class="cam-sheet-icon" style="background:#F0FDF4;color:#16A34A"><i class="fas fa-briefcase"></i></div>' +
      '<div class="cam-sheet-label"><strong>Domaine professionnel</strong>' +
        '<small>' + escHtml(profile.domain || 'Non défini') + '</small></div>' +
    '</button>' +

    '<button class="cam-sheet-btn" onclick="_closeGenericSheet(\'profil-settings\');openEditLocation()">' +
      '<div class="cam-sheet-icon" style="background:#FFF7ED;color:#EA580C"><i class="fas fa-location-dot"></i></div>' +
      '<div class="cam-sheet-label"><strong>Localisation</strong>' +
        '<small>' + escHtml(profile.location || 'Non définie') + '</small></div>' +
    '</button>' +

    '<button class="cam-sheet-btn" onclick="_closeGenericSheet(\'profil-settings\');openEditBio()">' +
      '<div class="cam-sheet-icon" style="background:#FDF4FF;color:#9333EA"><i class="fas fa-align-left"></i></div>' +
      '<div class="cam-sheet-label"><strong>À propos</strong>' +
        '<small>Modifier votre description</small></div>' +
    '</button>' +

    '<button class="cam-sheet-btn" onclick="_closeGenericSheet(\'profil-settings\');openEditSkills()">' +
      '<div class="cam-sheet-icon" style="background:#ECFDF5;color:#059669"><i class="fas fa-tags"></i></div>' +
      '<div class="cam-sheet-label"><strong>Compétences</strong>' +
        '<small>' + (profile.skills && profile.skills.length ? profile.skills.length + ' compétence(s)' : 'Aucune') + '</small></div>' +
    '</button>' +

    '<button class="cam-sheet-btn" onclick="_closeGenericSheet(\'profil-settings\');pickProfilePhoto()">' +
      '<div class="cam-sheet-icon" style="background:#F0F9FF;color:#0EA5E9"><i class="fas fa-camera"></i></div>' +
      '<div class="cam-sheet-label"><strong>Photo de profil</strong>' +
        '<small>Importer depuis la galerie</small></div>' +
    '</button>' +

    '<div class="cam-sheet-divider"></div>' +
    '<button class="cam-sheet-btn" onclick="_closeGenericSheet(\'profil-settings\')">' +
      '<div class="cam-sheet-icon cam-icon-cancel"><i class="fas fa-times"></i></div>' +
      '<div class="cam-sheet-label"><strong style="color:#EF4444">Fermer</strong></div>' +
    '</button>';

  document.body.appendChild(bg);
  document.body.appendChild(card);
}

function _closeGenericSheet(prefix) {
  var bg   = document.getElementById(prefix + '-bg');
  var card = document.getElementById(prefix + '-card');
  if (bg)   bg.remove();
  if (card) card.remove();
}

/* ── Feuille d'édition générique ── */
function _openEditSheet(title, bodyHtml, onSave) {
  _closeEditSheet();

  var bg = document.createElement('div');
  bg.className = 'cam-sheet-bg'; bg.id = 'edit-sheet-bg';
  bg.onclick = _closeEditSheet;

  var card = document.createElement('div');
  card.className = 'cam-sheet-card edit-sheet-card'; card.id = 'edit-sheet-card';
  card.innerHTML =
    '<div class="cam-sheet-handle"></div>' +
    '<div class="edit-sheet-head">' +
      '<p class="edit-sheet-title">' + escHtml(title) + '</p>' +
      '<button class="edit-sheet-close" onclick="_closeEditSheet()"><i class="fas fa-times"></i></button>' +
    '</div>' +
    '<div class="edit-sheet-body">' + bodyHtml + '</div>' +
    '<div class="edit-sheet-footer">' +
      '<button class="btn-outline edit-sheet-footer-cancel" onclick="_closeEditSheet()">Annuler</button>' +
      '<button class="btn-blue" id="edit-sheet-save-btn">Enregistrer</button>' +
    '</div>';

  document.body.appendChild(bg);
  document.body.appendChild(card);

  document.getElementById('edit-sheet-save-btn').onclick = function() {
    var ok = onSave();
    if (ok !== false) _closeEditSheet();
  };
}

function _closeEditSheet() {
  var bg   = document.getElementById('edit-sheet-bg');
  var card = document.getElementById('edit-sheet-card');
  if (bg)   bg.remove();
  if (card) card.remove();
}

/* ── Édition nom ── */
function openEditName() {
  var profile = loadUserProfile(_currentUser.email) || getDefaultProfile(_currentUser);
  _openEditSheet(
    'Modifier le nom',
    '<div class="edit-field-group">' +
      '<label>Nom complet</label>' +
      '<div class="edit-field-box">' +
        '<input type="text" id="edit-name-input" value="' + escHtml(profile.nom || '') +
        '" placeholder="Votre nom complet" maxlength="60"/>' +
      '</div>' +
    '</div>',
    function() {
      var val = (document.getElementById('edit-name-input').value || '').trim();
      if (!val) { showToast('Le nom ne peut pas être vide', ''); return false; }
      if (_gwIsReservedName(val)) { showToast('Ce nom est réservé au compte officiel Geniwork', 'err'); return false; }
      if (findUserByName(val, _currentUser.email)) { showToast('Ce nom est déjà utilisé par un autre membre. Choisissez-en un autre.', 'err'); return false; }
      var p = loadUserProfile(_currentUser.email) || getDefaultProfile(_currentUser);
      p.nom = val;
      saveUserProfile(_currentUser.email, p);
      /* Sync partout : session, gw_users, feed, notifications */
      _syncUserRecord(_currentUser.email, val);
      renderProfilePage();
      showToast('Nom mis à jour ✓', 'ok');
      return true;
    }
  );
  setTimeout(function() { var i = document.getElementById('edit-name-input'); if (i) { i.focus(); i.select(); } }, 320);
}

/* ── Édition domaine ── */
var DOMAIN_LIST = [
  'Développeur Web','Développeur Mobile','Développeur Fullstack',
  'Designer UI/UX','Designer Graphique','Motion Designer',
  'Marketing Digital','Community Manager','Gestionnaire Réseaux Sociaux',
  'Rédacteur / Copywriter','Consultant Business','Chef de Projet',
  'Data Analyst','Photographe','Vidéaste / Monteur',
  'Comptable / Financier','Consultant RH','Coach / Formateur',
  'Traducteur','Architecte','Ingénieur','Juriste / Avocat',
  'Musicien / Compositeur','Illustrateur','Technicien IT','Autre'
];

function openEditDomain() {
  var profile = loadUserProfile(_currentUser.email) || getDefaultProfile(_currentUser);
  var manualVal = (DOMAIN_LIST.indexOf(profile.domain) === -1 && profile.domain) ? profile.domain : '';

  var listHtml = DOMAIN_LIST.map(function(d) {
    var sel = d === profile.domain ? ' selected' : '';
    return '<button class="domain-option' + sel + '" onclick="selectDomainOption(this)">' + escHtml(d) + '</button>';
  }).join('');

  _openEditSheet(
    'Domaine professionnel',
    '<div class="edit-field-group">' +
      '<label>Entrer manuellement</label>' +
      '<div class="edit-field-box">' +
        '<input type="text" id="edit-domain-manual" placeholder="Ex : Consultant SEO" ' +
        'value="' + escHtml(manualVal) + '" maxlength="60" ' +
        'oninput="document.querySelectorAll(\'.domain-option\').forEach(function(b){b.classList.remove(\'selected\')})"/>' +
      '</div>' +
    '</div>' +
    '<div class="edit-field-group"><label>Ou choisir dans la liste</label></div>' +
    '<div class="domain-list">' + listHtml + '</div>',
    function() {
      var manual   = (document.getElementById('edit-domain-manual').value || '').trim();
      var selBtn   = document.querySelector('.domain-option.selected');
      var val      = manual || (selBtn ? selBtn.textContent.trim() : '');
      var p = loadUserProfile(_currentUser.email) || getDefaultProfile(_currentUser);
      p.domain = val;
      saveUserProfile(_currentUser.email, p);
      renderProfilePage();
      /* Le domaine apparaît dans les posts → re-render feed */
      if (document.getElementById('feed-list')) renderFeed(_getFeedPosts());
      showToast('Domaine mis à jour ✓', 'ok');
      return true;
    }
  );
}

function selectDomainOption(btn) {
  document.querySelectorAll('.domain-option').forEach(function(b) { b.classList.remove('selected'); });
  btn.classList.add('selected');
  var inp = document.getElementById('edit-domain-manual');
  if (inp) inp.value = '';
}

/* ── Édition bio ── */
function openEditBio() {
  var profile = loadUserProfile(_currentUser.email) || getDefaultProfile(_currentUser);
  var bioVal  = profile.bio || '';
  _openEditSheet(
    'À propos de vous',
    '<div class="edit-field-group">' +
      '<label>Description (max 500 caractères)</label>' +
      '<textarea id="edit-bio-input" class="edit-textarea" rows="6" maxlength="500" ' +
      'placeholder="Présentez-vous : votre expérience, vos spécialités...">' + escHtml(bioVal) + '</textarea>' +
      '<div class="edit-charcount"><span id="edit-bio-count">' + bioVal.length + '</span>/500</div>' +
    '</div>',
    function() {
      var val = (document.getElementById('edit-bio-input').value || '').trim();
      var p = loadUserProfile(_currentUser.email) || getDefaultProfile(_currentUser);
      p.bio = val;
      saveUserProfile(_currentUser.email, p);
      renderProfilePage();
      showToast('Description mise à jour', 'ok');
      return true;
    }
  );
  setTimeout(function() {
    var ta = document.getElementById('edit-bio-input');
    if (ta) {
      ta.focus();
      ta.addEventListener('input', function() {
        var cc = document.getElementById('edit-bio-count');
        if (cc) cc.textContent = ta.value.length;
      });
    }
  }, 320);
}

/* ── Édition localisation — GPS automatique ou saisie manuelle ── */
function openEditLocation() {
  var profile  = loadUserProfile(_currentUser.email) || getDefaultProfile(_currentUser);
  var curLoc   = profile.location || '';
  /* Sépare ville et pays depuis la valeur actuelle ex: "Paris, France" */
  var _curParts   = curLoc.split(',').map(function(s){ return s.trim(); });
  var _curCity    = _curParts[0] || '';
  var _curCountry = _curParts.slice(1).join(', ') || '';

  var html =
    /* ── Bouton GPS ── */
    '<div id="loc-gps-row" style="margin-bottom:16px">' +
      '<button type="button" id="loc-gps-btn" onclick="_locDetectGPS()" ' +
        'style="width:100%;display:flex;align-items:center;justify-content:center;gap:10px;' +
               'padding:13px;border-radius:14px;border:2px solid #6366F1;' +
               'background:linear-gradient(135deg,#EEF2FF,#F5F3FF);color:#4F46E5;' +
               'font-size:14px;font-weight:700;cursor:pointer;">' +
        '<i class="fas fa-location-arrow" style="font-size:16px"></i>' +
        'Détecter ma position automatiquement (GPS)' +
      '</button>' +
      '<p style="text-align:center;font-size:12px;color:#94A3B8;margin:8px 0 0">Détecte ton pays et ta ville via GPS</p>' +
    '</div>' +

    /* ── Résultat GPS ── */
    '<div id="loc-gps-result" style="display:none;background:#F0FDF4;border:1.5px solid #86EFAC;' +
         'border-radius:12px;padding:12px 14px;margin-bottom:16px;font-size:13px;color:#166534;">' +
      '<i class="fas fa-check-circle" style="margin-right:6px;color:#16A34A"></i>' +
      '<span id="loc-gps-text"></span>' +
    '</div>' +

    /* ── Séparateur ── */
    '<div style="display:flex;align-items:center;gap:10px;margin-bottom:16px;">' +
      '<div style="flex:1;height:1px;background:#E2E8F0"></div>' +
      '<span style="font-size:12px;color:#94A3B8;white-space:nowrap">ou saisir manuellement</span>' +
      '<div style="flex:1;height:1px;background:#E2E8F0"></div>' +
    '</div>' +

    /* ── Pays (prioritaire) ── */
    '<div class="edit-field-group" style="margin-bottom:12px">' +
      '<label style="display:flex;align-items:center;gap:6px">' +
        '<i class="fas fa-globe" style="color:#6366F1;font-size:13px"></i> Pays <span style="color:#EF4444;margin-left:2px">*</span>' +
      '</label>' +
      '<div class="edit-field-box">' +
        '<input type="text" id="loc-country-inp" value="' + escHtml(_curCountry) + '" ' +
               'placeholder="Ex : France, Cameroun, Canada…" maxlength="60" ' +
               'style="font-weight:600"/>' +
      '</div>' +
    '</div>' +

    /* ── Ville ── */
    '<div class="edit-field-group">' +
      '<label style="display:flex;align-items:center;gap:6px">' +
        '<i class="fas fa-map-marker-alt" style="color:#6366F1;font-size:13px"></i> Ville' +
      '</label>' +
      '<div class="edit-field-box">' +
        '<input type="text" id="loc-city-inp" value="' + escHtml(_curCity) + '" ' +
               'placeholder="Ex : Paris, Douala, Montréal…" maxlength="60"/>' +
      '</div>' +
    '</div>';

  _openEditSheet(
    '📍 Localisation',
    html,
    function() {
      var city    = (document.getElementById('loc-city-inp')    ? document.getElementById('loc-city-inp').value    : '').trim();
      var country = (document.getElementById('loc-country-inp') ? document.getElementById('loc-country-inp').value : '').trim();
      if (!country) { showToast('Le pays est requis', 'err'); return false; }
      var loc = city ? city + ', ' + country : country;
      var p = loadUserProfile(_currentUser.email) || getDefaultProfile(_currentUser);
      p.location = loc;
      saveUserProfile(_currentUser.email, p);
      renderProfilePage();
      showToast('📍 Localisation mise à jour : ' + loc, 'ok');
      return true;
    }
  );

  /* Focus sur le champ pays après ouverture */
  setTimeout(function() {
    var ci = document.getElementById('loc-country-inp');
    if (ci) ci.focus();
  }, 350);
}

/* Reverse-geocode lat/lng → ville + pays via Nominatim */
function _locReverseGeocode(lat, lng, btn) {
  fetch('https://nominatim.openstreetmap.org/reverse?format=json&lat=' + lat + '&lon=' + lng + '&accept-language=fr')
    .then(function(r) { return r.json(); })
    .then(function(data) {
      var addr    = data.address || {};
      var city    = addr.city || addr.town || addr.village || addr.municipality || addr.county || '';
      var country = addr.country || '';
      var ci = document.getElementById('loc-city-inp');
      var co = document.getElementById('loc-country-inp');
      if (ci) ci.value = city;
      if (co) { co.value = country; co.style.background = '#F0FDF4'; }
      var resBox = document.getElementById('loc-gps-result');
      var resTxt = document.getElementById('loc-gps-text');
      if (resBox && resTxt) { resTxt.textContent = (city ? city + ', ' : '') + country; resBox.style.display = 'block'; }
      if (btn) {
        btn.disabled = false;
        btn.innerHTML = '<i class="fas fa-check" style="font-size:16px;color:#16A34A"></i> Position détectée !';
        btn.style.borderColor = '#16A34A';
        btn.style.background  = 'linear-gradient(135deg,#F0FDF4,#DCFCE7)';
        btn.style.color       = '#166534';
      }
    })
    .catch(function() { _locGPSError('Impossible de récupérer l\'adresse — saisissez manuellement'); });
}

/* Détecte la position GPS et remplit les champs ville + pays */
function _locDetectGPS() {
  var btn = document.getElementById('loc-gps-btn');
  if (btn) {
    btn.disabled = true;
    btn.innerHTML = '<i class="fas fa-spinner fa-spin" style="font-size:16px"></i> Détection en cours…';
  }

  /* Utilise le plugin Capacitor Geolocation sur Android (demande la permission native) */
  var capGeo = window.Capacitor && window.Capacitor.Plugins && window.Capacitor.Plugins.Geolocation;
  if (capGeo) {
    capGeo.requestPermissions().then(function(permResult) {
      var state = (permResult && (permResult.location || permResult.coarseLocation)) || 'denied';
      if (state === 'denied' || state === 'prompt-with-rationale') {
        _locGPSError('Permission refusée — activez la localisation dans Paramètres > Applis > GENIWORK');
        return;
      }
      return capGeo.getCurrentPosition({ timeout: 10000, maximumAge: 60000 });
    }).then(function(pos) {
      if (!pos) return;
      _locReverseGeocode(pos.coords.latitude, pos.coords.longitude, btn);
    }).catch(function() {
      _locGPSError('GPS indisponible — saisissez manuellement');
    });
    return;
  }

  /* Fallback : navigator.geolocation (web) */
  if (!navigator.geolocation) {
    _locGPSError('GPS non supporté par votre navigateur');
    return;
  }
  navigator.geolocation.getCurrentPosition(
    function(pos) { _locReverseGeocode(pos.coords.latitude, pos.coords.longitude, btn); },
    function(err) {
      var msg = err.code === 1
        ? 'Permission GPS refusée — saisissez manuellement'
        : 'GPS indisponible — saisissez manuellement';
      _locGPSError(msg);
    },
    { timeout: 10000, maximumAge: 60000 }
  );
}

function _locGPSError(msg) {
  var btn = document.getElementById('loc-gps-btn');
  if (btn) {
    btn.disabled = false;
    btn.innerHTML = '<i class="fas fa-location-arrow" style="font-size:16px"></i> Réessayer le GPS';
    btn.style.borderColor = '#F87171';
    btn.style.background  = '#FFF5F5';
    btn.style.color       = '#DC2626';
  }
  showToast(msg, 'err');
}

