  var s = _admAiStatsData;
  var html = _admAiHeader('AI Agent — Consommation', 'Compteurs réels — gw/ai_usage_stats, alimentés à chaque appel IA depuis l\'activation de la collecte');
  var canExport = s && !s.error && s.hasData;
